/**
 * Secrets Management Module
 * 
 * Provides secure secrets loading from various sources:
 * - AWS Secrets Manager (production)
 * - HashiCorp Vault (alternative)
 * - Azure Key Vault (Azure environments)
 * - Environment variables (development only)
 * 
 * @module config/secrets
 */

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// Cache for loaded secrets (in-memory only, not persisted)
const secretsCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Configuration for secrets manager
 */
const config = {
  provider: process.env.SECRETS_PROVIDER || 'aws', // 'aws', 'vault', 'azure', 'env'
  aws: {
    region: process.env.AWS_REGION || 'us-east-1',
    secretPrefix: process.env.SECRETS_PREFIX || 'myapp/',
  },
  vault: {
    endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
    token: process.env.VAULT_TOKEN,
    path: process.env.VAULT_SECRET_PATH || 'secret/data/myapp',
  },
  azure: {
    vaultUrl: process.env.AZURE_KEY_VAULT_URL,
  },
  cache: {
    enabled: process.env.SECRETS_CACHE_ENABLED !== 'false',
    ttl: parseInt(process.env.SECRETS_CACHE_TTL || CACHE_TTL),
  },
};

/**
 * AWS Secrets Manager Client
 */
class AWSSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: config.aws.region,
    });
  }

  /**
   * Load secret from AWS Secrets Manager
   * @param {string} secretName - Name of the secret
   * @returns {Promise<Object>} Secret value (parsed JSON or string)
   */
  async getSecret(secretName) {
    const fullSecretName = `${config.aws.secretPrefix}${secretName}`;

    try {
      const command = new GetSecretValueCommand({
        SecretId: fullSecretName,
      });

      const response = await this.client.send(command);

      // Parse JSON secrets or return string
      if (response.SecretString) {
        try {
          return JSON.parse(response.SecretString);
        } catch {
          return response.SecretString;
        }
      }

      // Handle binary secrets
      if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary).toString('utf-8');
      }

      throw new Error('Secret value not found');
    } catch (error) {
      console.error(`Error loading secret ${fullSecretName}:`, error.message);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }
}

/**
 * HashiCorp Vault Client
 */
class VaultSecretsManager {
  constructor() {
    this.endpoint = config.vault.endpoint;
    this.token = config.vault.token;
    this.path = config.vault.path;

    if (!this.token) {
      throw new Error('VAULT_TOKEN not configured');
    }
  }

  /**
   * Load secret from HashiCorp Vault
   * @param {string} secretName - Name of the secret
   * @returns {Promise<Object>} Secret value
   */
  async getSecret(secretName) {
    const url = `${this.endpoint}/v1/${this.path}/${secretName}`;

    try {
      const response = await fetch(url, {
        headers: {
          'X-Vault-Token': this.token,
        },
      });

      if (!response.ok) {
        throw new Error(`Vault returned ${response.status}`);
      }

      const data = await response.json();
      return data.data.data; // KV v2 response structure
    } catch (error) {
      console.error(`Error loading secret ${secretName} from Vault:`, error.message);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }
}

/**
 * Azure Key Vault Client
 */
class AzureSecretsManager {
  constructor() {
    const { DefaultAzureCredential } = require('@azure/identity');
    const { SecretClient } = require('@azure/keyvault-secrets');

    if (!config.azure.vaultUrl) {
      throw new Error('AZURE_KEY_VAULT_URL not configured');
    }

    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(config.azure.vaultUrl, credential);
  }

  /**
   * Load secret from Azure Key Vault
   * @param {string} secretName - Name of the secret
   * @returns {Promise<string>} Secret value
   */
  async getSecret(secretName) {
    try {
      const secret = await this.client.getSecret(secretName);

      // Try to parse as JSON
      try {
        return JSON.parse(secret.value);
      } catch {
        return secret.value;
      }
    } catch (error) {
      console.error(`Error loading secret ${secretName} from Azure:`, error.message);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }
}

/**
 * Environment Variables (Development Only)
 * WARNING: Only use in local development, never in production
 */
class EnvSecretsManager {
  constructor() {
    if (process.env.NODE_ENV === 'production') {
      console.warn('⚠️  WARNING: Using environment variables for secrets in production is insecure!');
    }
  }

  async getSecret(secretName) {
    const value = process.env[secretName.toUpperCase().replace(/[/-]/g, '_')];

    if (!value) {
      throw new Error(`Secret ${secretName} not found in environment`);
    }

    // Try to parse as JSON
    try {
      return JSON.parse(value);
    } catch {
      return value;
    }
  }
}

/**
 * Factory to create appropriate secrets manager
 */
function createSecretsManager() {
  switch (config.provider) {
    case 'aws':
      return new AWSSecretsManager();
    case 'vault':
      return new VaultSecretsManager();
    case 'azure':
      return new AzureSecretsManager();
    case 'env':
      return new EnvSecretsManager();
    default:
      throw new Error(`Unknown secrets provider: ${config.provider}`);
  }
}

/**
 * Main Secrets Manager with caching
 */
class SecretsManager {
  constructor() {
    this.provider = createSecretsManager();
  }

  /**
   * Get secret with caching
   * @param {string} secretName - Name of the secret
   * @param {boolean} forceRefresh - Force refresh from source
   * @returns {Promise<any>} Secret value
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && config.cache.enabled) {
      const cached = secretsCache.get(secretName);
      if (cached && Date.now() - cached.timestamp < config.cache.ttl) {
        return cached.value;
      }
    }

    // Load from provider
    const value = await this.provider.getSecret(secretName);

    // Cache the result
    if (config.cache.enabled) {
      secretsCache.set(secretName, {
        value,
        timestamp: Date.now(),
      });
    }

    return value;
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<Object>} Object with secret names as keys
   */
  async getSecrets(secretNames) {
    const results = await Promise.all(
      secretNames.map(async (name) => {
        try {
          const value = await this.getSecret(name);
          return { name, value, error: null };
        } catch (error) {
          return { name, value: null, error: error.message };
        }
      })
    );

    const secrets = {};
    const errors = [];

    results.forEach(({ name, value, error }) => {
      if (error) {
        errors.push({ name, error });
      } else {
        secrets[name] = value;
      }
    });

    if (errors.length > 0) {
      console.error('Failed to load some secrets:', errors);
    }

    return secrets;
  }

  /**
   * Clear cache (useful for testing or forced refresh)
   */
  clearCache() {
    secretsCache.clear();
  }

  /**
   * Rotate secret (trigger re-fetch on next access)
   * @param {string} secretName - Name of the secret to rotate
   */
  rotateSecret(secretName) {
    secretsCache.delete(secretName);
  }
}

// Singleton instance
let secretsManager = null;

/**
 * Get secrets manager instance
 * @returns {SecretsManager}
 */
function getSecretsManager() {
  if (!secretsManager) {
    secretsManager = new SecretsManager();
  }
  return secretsManager;
}

/**
 * Initialize all required secrets on startup
 * This ensures all secrets are available before the app starts
 * 
 * @returns {Promise<Object>} All application secrets
 */
async function initializeSecrets() {
  const manager = getSecretsManager();

  const secretNames = [
    'database-url',
    'jwt-secret',
    'api-token',
    'aws-access-key',
    'aws-secret-key',
    'stripe-secret-key',
    'anthropic-api-key',
  ];

  try {
    console.log('🔐 Loading secrets from', config.provider);
    const secrets = await manager.getSecrets(secretNames);
    console.log('✅ Secrets loaded successfully');
    return secrets;
  } catch (error) {
    console.error('❌ Failed to initialize secrets:', error);
    throw error;
  }
}

/**
 * Helper to get a single secret (convenience method)
 * @param {string} secretName - Name of the secret
 * @returns {Promise<any>} Secret value
 */
async function getSecret(secretName) {
  const manager = getSecretsManager();
  return manager.getSecret(secretName);
}

module.exports = {
  getSecretsManager,
  initializeSecrets,
  getSecret,
  config,
};

/**
 * Secure Express Application with Secrets Manager Integration
 * 
 * This application demonstrates best practices for:
 * - Secrets management using cloud providers
 * - Security headers and middleware
 * - Input validation and sanitization
 * - Authentication and authorization
 * - Rate limiting and DoS protection
 * 
 * @module app
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const hpp = require('hpp');
const mongoSanitize = require('express-mongo-sanitize');

// Import secrets manager
const { initializeSecrets, getSecret } = require('./config/secrets');

const app = express();

// Store loaded secrets (initialized at startup)
let appSecrets = null;

/**
 * Initialize application with secrets
 * This must be called before starting the server
 */
async function initializeApp() {
  try {
    // Load all secrets at startup
    appSecrets = await initializeSecrets();

    // Verify critical secrets are present
    const requiredSecrets = ['jwt-secret', 'database-url'];
    for (const secretName of requiredSecrets) {
      if (!appSecrets[secretName]) {
        throw new Error(`Required secret missing: ${secretName}`);
      }
    }

    console.log('✅ Application secrets initialized');
    return true;
  } catch (error) {
    console.error('❌ Failed to initialize application:', error);
    throw error;
  }
}

// ===========================
// SECURITY MIDDLEWARE
// ===========================

// 1. Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xssFilter: true,
  hidePoweredBy: true,
  frameguard: { action: 'deny' }
}));

// 2. CORS Configuration
const corsOptions = {
  origin: function (origin, callback) {
    // Load allowed origins from secrets/config
    const whitelist = ['http://localhost:3000', 'https://yourdomain.com'];

    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests to this endpoint, please try again later.',
});

// 4. Body Parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Sanitization
app.use(mongoSanitize());
app.use(hpp());

// 6. Logging
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// 7. Request ID for tracking
app.use((req, res, next) => {
  req.id = require('crypto').randomUUID();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ===========================
// AUTHENTICATION MIDDLEWARE
// ===========================

/**
 * JWT Authentication Middleware
 * Uses JWT secret loaded from secrets manager
 */
const authenticateToken = async (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No token provided.' 
    });
  }

  try {
    // In production, use JWT verification with secret from secrets manager
    const jwt = require('jsonwebtoken');
    const jwtSecret = await getSecret('jwt-secret');

    const decoded = jwt.verify(token, jwtSecret);
    req.user = decoded;
    next();
  } catch (err) {
    // Log the error for security monitoring
    console.error(`[${req.id}] Authentication failed:`, err.message);
    return res.status(403).json({ 
      error: 'Invalid or expired token' 
    });
  }
};

/**
 * API Key Authentication (for service-to-service calls)
 */
const authenticateApiKey = async (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ 
      error: 'API key required' 
    });
  }

  try {
    // Compare with secret stored in secrets manager
    const validApiKey = await getSecret('api-token');

    if (apiKey !== validApiKey) {
      throw new Error('Invalid API key');
    }

    req.authenticated = true;
    next();
  } catch (err) {
    console.error(`[${req.id}] API key authentication failed:`, err.message);
    return res.status(403).json({ 
      error: 'Invalid API key' 
    });
  }
};

// ===========================
// INPUT VALIDATION HELPERS
// ===========================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ===========================
// ROUTES
// ===========================

// Health check - Public endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    secretsProvider: require('./config/secrets').config.provider
  });
});

// Secrets status endpoint (for debugging - remove in production)
app.get('/debug/secrets-status', async (req, res) => {
  // Only available in development
  if (process.env.NODE_ENV === 'production') {
    return res.status(404).json({ error: 'Not found' });
  }

  res.json({
    provider: require('./config/secrets').config.provider,
    secretsLoaded: appSecrets !== null,
    availableSecrets: appSecrets ? Object.keys(appSecrets) : [],
    // Never expose actual secret values
  });
});

// Users endpoint - Protected
app.get('/users', 
  authenticateToken,
  strictLimiter,
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    handleValidationErrors
  ],
  async (req, res) => {
    try {
      // Example: Use database URL from secrets manager
      // const dbUrl = await getSecret('database-url');
      // const db = await connectToDatabase(dbUrl);

      const allUsers = [
        { id: 1, name: 'Alice', role: 'admin' },
        { id: 2, name: 'Bob', role: 'user' },
      ];

      const sanitizedUsers = allUsers.map(user => ({
        id: user.id,
        name: user.name,
        role: user.role,
        ...(req.user.role === 'admin' || req.user.id === user.id 
          ? { email: `${user.name.toLowerCase()}@example.com` } 
          : {})
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          page: parseInt(req.query.page) || 1,
          limit: parseInt(req.query.limit) || 10,
          total: allUsers.length
        }
      });
    } catch (error) {
      console.error(`[${req.id}] Error in /users:`, error);
      res.status(500).json({ 
        error: 'Internal server error' 
      });
    }
  }
);

// Example: Payment endpoint using Stripe secret
app.post('/payments/charge',
  authenticateToken,
  strictLimiter,
  [
    body('amount')
      .isInt({ min: 1 })
      .withMessage('Amount must be a positive integer'),
    body('currency')
      .isIn(['usd', 'eur', 'gbp'])
      .withMessage('Invalid currency'),
    handleValidationErrors
  ],
  async (req, res) => {
    try {
      // Load Stripe secret from secrets manager
      const stripeSecretKey = await getSecret('stripe-secret-key');

      // Never log the actual secret
      console.log(`[${req.id}] Processing payment with Stripe`);

      // In production: Use the secret to initialize Stripe
      // const stripe = require('stripe')(stripeSecretKey);
      // const charge = await stripe.charges.create({ ... });

      res.json({
        message: 'Payment processed successfully',
        // Return safe, non-sensitive data only
      });
    } catch (error) {
      console.error(`[${req.id}] Payment processing failed:`, error.message);
      res.status(500).json({ 
        error: 'Payment processing failed' 
      });
    }
  }
);

// ===========================
// ERROR HANDLING
// ===========================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log error details internally (consider using a secure logging service)
  console.error(`[${req.id || 'unknown'}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===========================
// SERVER STARTUP
// ===========================

const PORT = process.env.PORT || 3000;

/**
 * Start the server (only if not in test mode)
 */
async function startServer() {
  if (process.env.NODE_ENV === 'test') {
    return app; // Return app for testing without starting server
  }

  try {
    // Initialize secrets before starting server
    await initializeApp();

    const server = app.listen(PORT, () => {
      console.log(`🔒 Secure server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`Secrets Provider: ${require('./config/secrets').config.provider}`);
    });

    // Graceful shutdown
    const shutdown = () => {
      console.log('Shutting down gracefully...');
      server.close(() => {
        console.log('✅ Server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('⚠️  Forcing shutdown');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', shutdown);
    process.on('SIGINT', shutdown);

    return server;
  } catch (error) {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  }
}

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = app;
module.exports.startServer = startServer;
module.exports.initializeApp = initializeApp;

#!/usr/bin/env node
/**
 * Secrets Detection Script
 * 
 * Scans the codebase for:
 * - Hardcoded secrets
 * - API keys
 * - Passwords
 * - Tokens
 * - Private keys
 * 
 * Usage: node scripts/check-secrets.js
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Patterns to detect secrets
const SECRET_PATTERNS = [
  {
    name: 'AWS Access Key',
    pattern: /AKIA[0-9A-Z]{16}/g,
    severity: 'CRITICAL'
  },
  {
    name: 'AWS Secret Key',
    pattern: /aws_secret_access_key\s*=\s*['"]?([A-Za-z0-9/+=]{40})['"]?/gi,
    severity: 'CRITICAL'
  },
  {
    name: 'Private Key',
    pattern: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/g,
    severity: 'CRITICAL'
  },
  {
    name: 'Generic API Key',
    pattern: /api[_-]?key['"]?\s*[:=]\s*['"]([A-Za-z0-9_\-]{20,})/gi,
    severity: 'HIGH'
  },
  {
    name: 'Generic Secret',
    pattern: /secret['"]?\s*[:=]\s*['"]([A-Za-z0-9_\-]{20,})/gi,
    severity: 'HIGH'
  },
  {
    name: 'Password',
    pattern: /password['"]?\s*[:=]\s*['"]([^'"]{8,})/gi,
    severity: 'HIGH'
  },
  {
    name: 'JWT Token',
    pattern: /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g,
    severity: 'HIGH'
  },
  {
    name: 'Stripe Key',
    pattern: /sk_(live|test)_[0-9a-zA-Z]{24,}/g,
    severity: 'CRITICAL'
  },
  {
    name: 'GitHub Token',
    pattern: /gh[ps]_[A-Za-z0-9]{36,}/g,
    severity: 'CRITICAL'
  },
  {
    name: 'Slack Token',
    pattern: /xox[baprs]-[0-9]{10,13}-[0-9]{10,13}-[A-Za-z0-9]{24,}/g,
    severity: 'HIGH'
  },
  {
    name: 'Database URL with password',
    pattern: /(?:postgres|mysql|mongodb):\/\/[^:]+:([^@]{8,})@/gi,
    severity: 'CRITICAL'
  },
  {
    name: 'Bearer Token',
    pattern: /Bearer\s+[A-Za-z0-9_\-\.]{20,}/gi,
    severity: 'HIGH'
  },
  {
    name: 'Anthropic API Key',
    pattern: /sk-ant-api[0-9]{2}-[A-Za-z0-9_-]{95}/g,
    severity: 'CRITICAL'
  },
];

// Files/directories to skip
const IGNORE_PATTERNS = [
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.env.example',
  'check-secrets.js', // This file
  'SECRETS_MANAGEMENT_GUIDE.md', // Documentation
];

// Canary tokens that are intentional (for testing)
const KNOWN_CANARY_TOKENS = [
  'CANARY',
  'FAKE',
  'EXAMPLE',
  'TEST-',
  'DUMMY',
];

class SecretsScanner {
  constructor() {
    this.findings = [];
    this.filesScanned = 0;
  }

  /**
   * Check if a finding is a known canary/test value
   */
  isCanaryToken(match) {
    return KNOWN_CANARY_TOKENS.some(canary => 
      match.toUpperCase().includes(canary)
    );
  }

  /**
   * Scan a file for secrets
   */
  scanFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      this.filesScanned++;

      SECRET_PATTERNS.forEach(({ name, pattern, severity }) => {
        let match;
        pattern.lastIndex = 0; // Reset regex state

        while ((match = pattern.exec(content)) !== null) {
          const matchedText = match[0];
          const lineNumber = content.substring(0, match.index).split('\n').length;

          // Check if it's a canary token
          const isCanary = this.isCanaryToken(matchedText);

          this.findings.push({
            file: filePath,
            line: lineNumber,
            type: name,
            severity: isCanary ? 'INFO' : severity,
            match: matchedText.substring(0, 50) + '...', // Truncate for safety
            isCanary,
          });
        }
      });
    } catch (error) {
      // Skip files that can't be read
      if (error.code !== 'EISDIR') {
        console.error(`Error scanning ${filePath}:`, error.message);
      }
    }
  }

  /**
   * Recursively scan directory
   */
  scanDirectory(dirPath) {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);

      // Skip ignored patterns
      if (IGNORE_PATTERNS.some(pattern => fullPath.includes(pattern))) {
        continue;
      }

      if (entry.isDirectory()) {
        this.scanDirectory(fullPath);
      } else if (entry.isFile()) {
        // Only scan text files
        const ext = path.extname(entry.name).toLowerCase();
        if (['.js', '.ts', '.json', '.env', '.yml', '.yaml', '.xml', '.txt', '.md', '.sh'].includes(ext) || 
            entry.name.startsWith('.env')) {
          this.scanFile(fullPath);
        }
      }
    }
  }

  /**
   * Check git history for secrets
   */
  checkGitHistory() {
    try {
      console.log('\n🔍 Checking git history for secrets...\n');

      // Check if we're in a git repository
      execSync('git rev-parse --git-dir', { stdio: 'pipe' });

      // Use git log to search for potential secrets
      const gitLog = execSync(
        'git log --all --full-history --pretty=format:"%H %s" | head -100',
        { encoding: 'utf8', stdio: 'pipe' }
      );

      console.log('✅ Git history check available');
      console.log('⚠️  Consider using tools like:');
      console.log('   - gitleaks: https://github.com/gitleaks/gitleaks');
      console.log('   - truffleHog: https://github.com/trufflesecurity/trufflehog');
      console.log('   - git-secrets: https://github.com/awslabs/git-secrets');

    } catch (error) {
      console.log('ℹ️  Not a git repository or git not available');
    }
  }

  /**
   * Generate report
   */
  generateReport() {
    console.log('\n' + '='.repeat(80));
    console.log('🔐 SECRETS DETECTION REPORT');
    console.log('='.repeat(80) + '\n');

    console.log(`Files scanned: ${this.filesScanned}`);
    console.log(`Potential secrets found: ${this.findings.length}\n`);

    if (this.findings.length === 0) {
      console.log('✅ No secrets detected!\n');
      return 0;
    }

    // Group by severity
    const bySeverity = {
      CRITICAL: [],
      HIGH: [],
      INFO: [],
    };

    this.findings.forEach(finding => {
      bySeverity[finding.severity].push(finding);
    });

    // Report critical findings
    if (bySeverity.CRITICAL.length > 0) {
      console.log('🚨 CRITICAL FINDINGS (Immediate action required!):\n');
      bySeverity.CRITICAL.forEach((finding, i) => {
        console.log(`${i + 1}. ${finding.file}:${finding.line}`);
        console.log(`   Type: ${finding.type}`);
        console.log(`   Match: ${finding.match}`);
        console.log('');
      });
    }

    // Report high severity findings
    if (bySeverity.HIGH.length > 0) {
      console.log('⚠️  HIGH SEVERITY FINDINGS:\n');
      bySeverity.HIGH.forEach((finding, i) => {
        console.log(`${i + 1}. ${finding.file}:${finding.line}`);
        console.log(`   Type: ${finding.type}`);
        console.log(`   Match: ${finding.match}`);
        console.log('');
      });
    }

    // Report canary tokens (informational)
    if (bySeverity.INFO.length > 0) {
      console.log('ℹ️  CANARY TOKENS (Test/Example values):\n');
      bySeverity.INFO.forEach((finding, i) => {
        console.log(`${i + 1}. ${finding.file}:${finding.line}`);
        console.log(`   Type: ${finding.type}`);
        console.log('');
      });
    }

    // Recommendations
    console.log('\n' + '='.repeat(80));
    console.log('📋 RECOMMENDATIONS:');
    console.log('='.repeat(80) + '\n');

    if (bySeverity.CRITICAL.length > 0 || bySeverity.HIGH.length > 0) {
      console.log('1. IMMEDIATELY rotate any exposed credentials');
      console.log('2. Move secrets to a secrets manager (AWS, Vault, Azure)');
      console.log('3. Remove secrets from version control:');
      console.log('   git filter-branch --force --index-filter \\');
      console.log('     "git rm --cached --ignore-unmatch PATH/TO/FILE" \\');
      console.log('     --prune-empty --tag-name-filter cat -- --all');
      console.log('4. Add .gitignore rules to prevent future commits');
      console.log('5. Enable pre-commit hooks to scan for secrets');
      console.log('6. Review access logs for unauthorized usage');
      console.log('\nSee SECRETS_MANAGEMENT_GUIDE.md for detailed instructions.');
    }

    // Return exit code
    return bySeverity.CRITICAL.length > 0 ? 1 : 0;
  }

  /**
   * Run the scan
   */
  run() {
    console.log('🔍 Scanning for hardcoded secrets...\n');

    const startDir = process.cwd();
    this.scanDirectory(startDir);
    this.checkGitHistory();

    return this.generateReport();
  }
}

// Run the scanner
if (require.main === module) {
  const scanner = new SecretsScanner();
  const exitCode = scanner.run();
  process.exit(exitCode);
}

module.exports = SecretsScanner;

