// scripts/rotate-secrets.js
const { SecretsManagerClient, UpdateSecretCommand } = require("@aws-sdk/client-secrets-manager");
const crypto = require('crypto');

async function rotateSecret(secretName) {
  const client = new SecretsManagerClient({ region: "us-east-1" });

  // Generate new secret
  const newSecret = crypto.randomBytes(32).toString('hex');

  const command = new UpdateSecretCommand({
    SecretId: secretName,
    SecretString: JSON.stringify({ key: newSecret }),
  });

  try {
    await client.send(command);
    console.log(`✅ Rotated secret: ${secretName}`);
  } catch (error) {
    console.error(`❌ Failed to rotate ${secretName}:`, error);
    throw error;
  }
}

// Run rotation
async function main() {
  const secrets = [
    'prod/anthropic/api-key',
    'prod/logfire/token',
  ];

  for (const secret of secrets) {
    await rotateSecret(secret);
  }
}

if (require.main === module) {
  main().catch(console.error);
}
