### Scenario 2: SQL Injection Attack

#### ❌ Original Vulnerability
```javascript
// If database added without protection:
app.get('/user/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query); // VULNERABLE!
});

// Attack: GET /user/1 OR 1=1; DROP TABLE users; --
// Result: Database destroyed
```

#### ✅ Secure Defense
```javascript
app.get('/api/users/:id',
  authenticateAPIKey,
  [
    param('id').isInt({ min: 1 }).toInt()
  ],
  validateRequest,
  (req, res) => {
    const userId = req.params.id; // Already validated as integer

    // Parameterized query
    db.query('SELECT * FROM users WHERE id = $1', [userId]);

    // Attack attempt: GET /api/users/1 OR 1=1
    // Response: 400 Bad Request - Validation failed
  }
);
```

