// 🔐 Secure Secrets Management Module
// Supports multiple secrets management providers

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const vault = require('node-vault');
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

/**
 * Abstract Secrets Manager Interface
 * Provides a unified interface for multiple secret management providers
 */
class SecretsManager {
  constructor(provider, config = {}) {
    this.provider = provider.toLowerCase();
    this.config = config;
    this.cache = new Map();
    this.cacheExpiry = config.cacheExpiry || 300000; // 5 minutes default
    this.client = null;

    this.initializeClient();
  }

  /**
   * Initialize the appropriate secrets management client
   */
  initializeClient() {
    switch (this.provider) {
      case 'aws':
        this.client = new SecretsManagerClient({
          region: this.config.region || process.env.AWS_REGION || 'us-east-1'
        });
        break;

      case 'gcp':
        this.client = new SecretManagerServiceClient({
          projectId: this.config.projectId || process.env.GCP_PROJECT_ID
        });
        break;

      case 'azure':
        const credential = new DefaultAzureCredential();
        this.client = new SecretClient(
          this.config.vaultUrl || process.env.AZURE_VAULT_URL,
          credential
        );
        break;

      case 'vault':
        this.client = vault({
          endpoint: this.config.endpoint || process.env.VAULT_ENDPOINT || 'http://127.0.0.1:8200',
          token: this.config.token || process.env.VAULT_TOKEN
        });
        break;

      case 'env':
        // Fallback to environment variables (NOT recommended for production)
        console.warn('⚠️  WARNING: Using environment variables for secrets. Not recommended for production!');
        this.client = null;
        break;

      default:
        throw new Error(`Unsupported secrets provider: ${this.provider}`);
    }
  }

  /**
   * Get a secret with caching
   */
  async getSecret(secretName, options = {}) {
    const cacheKey = `${this.provider}:${secretName}`;

    // Check cache if enabled
    if (!options.skipCache && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() < cached.expiry) {
        return cached.value;
      }
      this.cache.delete(cacheKey);
    }

    // Fetch secret based on provider
    let secretValue;
    try {
      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAWSSecret(secretName);
          break;
        case 'gcp':
          secretValue = await this.getGCPSecret(secretName);
          break;
        case 'azure':
          secretValue = await this.getAzureSecret(secretName);
          break;
        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;
        case 'env':
          secretValue = this.getEnvSecret(secretName);
          break;
      }

      // Cache the secret
      if (!options.skipCache) {
        this.cache.set(cacheKey, {
          value: secretValue,
          expiry: Date.now() + this.cacheExpiry
        });
      }

      this.logSecretAccess(secretName, 'success');
      return secretValue;

    } catch (error) {
      this.logSecretAccess(secretName, 'failed', error);
      throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * AWS Secrets Manager implementation
   */
  async getAWSSecret(secretName) {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT'
    });

    const response = await this.client.send(command);

    // Secrets can be string or binary
    if (response.SecretString) {
      try {
        return JSON.parse(response.SecretString);
      } catch {
        return response.SecretString;
      }
    }

    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    throw new Error('Secret value not found');
  }

  /**
   * Google Cloud Secret Manager implementation
   */
  async getGCPSecret(secretName) {
    const projectId = this.config.projectId || process.env.GCP_PROJECT_ID;
    const name = `projects/${projectId}/secrets/${secretName}/versions/latest`;

    const [version] = await this.client.accessSecretVersion({ name });
    const payload = version.payload.data.toString();

    try {
      return JSON.parse(payload);
    } catch {
      return payload;
    }
  }

  /**
   * Azure Key Vault implementation
   */
  async getAzureSecret(secretName) {
    const secret = await this.client.getSecret(secretName);

    try {
      return JSON.parse(secret.value);
    } catch {
      return secret.value;
    }
  }

  /**
   * HashiCorp Vault implementation
   */
  async getVaultSecret(secretName) {
    const mountPath = this.config.mountPath || 'secret';
    const result = await this.client.read(`${mountPath}/data/${secretName}`);

    if (!result || !result.data || !result.data.data) {
      throw new Error('Secret not found or invalid format');
    }

    return result.data.data;
  }

  /**
   * Environment variables fallback (NOT RECOMMENDED)
   */
  getEnvSecret(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Environment variable ${secretName} not found`);
    }
    return value;
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretNames) {
    const secrets = {};
    const promises = secretNames.map(async (name) => {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        console.error(`Failed to load secret ${name}:`, error.message);
        secrets[name] = null;
      }
    });

    await Promise.all(promises);
    return secrets;
  }

  /**
   * Validate that required secrets are available
   */
  async validateSecrets(requiredSecrets) {
    const missing = [];

    for (const secretName of requiredSecrets) {
      try {
        await this.getSecret(secretName);
      } catch (error) {
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }

  /**
   * Clear the cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Log secret access for audit trail
   */
  logSecretAccess(secretName, status, error = null) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      provider: this.provider,
      secret: secretName,
      status,
      error: error ? error.message : null
    };

    // In production, send to SIEM or logging service
    if (process.env.NODE_ENV === 'production') {
      console.log(JSON.stringify(logEntry));
    }
  }
}

/**
 * Factory function to create secrets manager instance
 */
function createSecretsManager(options = {}) {
  const provider = options.provider || 
                   process.env.SECRETS_PROVIDER || 
                   'env';

  return new SecretsManager(provider, options);
}

/**
 * Singleton instance for application-wide use
 */
let secretsManagerInstance = null;

function getSecretsManager(options = {}) {
  if (!secretsManagerInstance) {
    secretsManagerInstance = createSecretsManager(options);
  }
  return secretsManagerInstance;
}

/**
 * Helper to load application secrets on startup
 */
async function loadApplicationSecrets() {
  const manager = getSecretsManager();

  const requiredSecrets = [
    'DATABASE_URL',
    'JWT_SECRET',
    'VALID_API_KEYS'
  ];

  const optionalSecrets = [
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  try {
    // Validate required secrets exist
    await manager.validateSecrets(requiredSecrets);

    // Load all secrets
    const allSecrets = [...requiredSecrets, ...optionalSecrets];
    const secrets = await manager.getSecrets(allSecrets);

    console.log('✅ Successfully loaded application secrets');

    return secrets;
  } catch (error) {
    console.error('❌ Failed to load application secrets:', error.message);
    throw error;
  }
}

/**
 * Kubernetes Secrets helper (reads from mounted files)
 */
class KubernetesSecretsManager {
  constructor(secretsPath = '/var/run/secrets') {
    this.secretsPath = secretsPath;
  }

  async getSecret(secretName) {
    const fs = require('fs').promises;
    const path = require('path');

    try {
      const secretPath = path.join(this.secretsPath, secretName);
      const value = await fs.readFile(secretPath, 'utf8');
      return value.trim();
    } catch (error) {
      throw new Error(`Failed to read Kubernetes secret ${secretName}: ${error.message}`);
    }
  }
}

/**
 * Docker Secrets helper (reads from /run/secrets)
 */
class DockerSecretsManager {
  constructor(secretsPath = '/run/secrets') {
    this.secretsPath = secretsPath;
  }

  async getSecret(secretName) {
    const fs = require('fs').promises;
    const path = require('path');

    try {
      const secretPath = path.join(this.secretsPath, secretName);
      const value = await fs.readFile(secretPath, 'utf8');
      return value.trim();
    } catch (error) {
      throw new Error(`Failed to read Docker secret ${secretName}: ${error.message}`);
    }
  }
}

module.exports = {
  SecretsManager,
  createSecretsManager,
  getSecretsManager,
  loadApplicationSecrets,
  KubernetesSecretsManager,
  DockerSecretsManager
};

