    userAgent: req.get('user-agent'),
    path: req.path,
    ...details
  }));
};

// ============================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================
const authenticateAPIKey = (req, res, next) => {
  const apiKey = req.header('X-API-Key');

  if (!apiKey) {
    logSecurityEvent('AUTH_MISSING_API_KEY', req);
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'API key is missing'
    });
  }

  // Get valid API keys from secrets manager
  const validAPIKeysString = getSecret('VALID_API_KEYS', '');
  const validAPIKeys = validAPIKeysString.split(',').map(k => k.trim());

  if (!validAPIKeys.includes(apiKey)) {
    logSecurityEvent('AUTH_INVALID_API_KEY', req, { apiKey: apiKey.substring(0, 8) + '...' });
    return res.status(403).json({ 
      error: 'Access denied',
      message: 'Invalid API key'
    });
  }

  next();
};

// ============================================
// 7. AUTHORIZATION MIDDLEWARE
// ============================================
const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    const userRole = req.header('X-User-Role') || 'guest';

    if (!allowedRoles.includes(userRole)) {
      logSecurityEvent('AUTHORIZATION_DENIED', req, { 
        userRole, 
        requiredRoles: allowedRoles 
      });
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'Insufficient permissions'
      });
    }

    next();
  };
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    secretsManager: process.env.SECRETS_PROVIDER || 'env'
  });
});

// Secret rotation endpoint (admin only)
app.post('/api/admin/refresh-secrets',
  authenticateAPIKey,
  requireRole(['admin']),
  async (req, res) => {
    try {
      const success = await refreshSecrets();

      if (success) {
        logSecurityEvent('SECRETS_REFRESHED', req);
        res.json({ 
          message: 'Secrets refreshed successfully',
          timestamp: new Date().toISOString()
        });
      } else {
        res.status(500).json({ 
          error: 'Failed to refresh secrets',
          message: 'Check server logs for details'
        });
      }
    } catch (error) {
      logSecurityEvent('SECRETS_REFRESH_FAILED', req, { error: error.message });
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'Failed to refresh secrets'
      });
    }
  }
);

// Protected users endpoint
app.get('/api/users', 
  authenticateAPIKey,
  requireRole(['admin', 'user']),
  strictLimiter,
  [
    query('page').optional().isInt({ min: 1 }),
    query('limit').optional().isInt({ min: 1, max: 100 }),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Validation failed', details: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({ data: users });
  }
);

// ============================================
// ERROR HANDLING
// ============================================
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not found',
    message: 'The requested resource does not exist'
  });
});

app.use((err, req, res, next) => {
  logSecurityEvent('UNHANDLED_ERROR', req, { error: err.message });
  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An unexpected error occurred' : err.message
  });
});

// ============================================
// SERVER STARTUP WITH SECRETS INITIALIZATION
// ============================================
async function startServer() {
  try {
    // Initialize secrets before starting server
    await initializeSecrets();

    const PORT = process.env.PORT || 3000;
    const HOST = process.env.HOST || '0.0.0.0';

    const server = app.listen(PORT, HOST, () => {
      console.log(`✅ Server running on http://${HOST}:${PORT}`);
      console.log(`📊 Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`🔐 Secrets Provider: ${process.env.SECRETS_PROVIDER || 'environment variables'}`);

      if (process.env.NODE_ENV !== 'production') {
        console.warn('⚠️  WARNING: Not running in production mode');
      }

      if (!process.env.SECRETS_PROVIDER || process.env.SECRETS_PROVIDER === 'env') {
        console.warn('⚠️  WARNING: Using environment variables for secrets. Use a secrets manager in production!');
      }
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });
    });

    return server;
  } catch (error) {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  }
}

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = { app, startServer, getSecret, refreshSecrets };

