/**
 * Secure Secrets Manager Implementation
 * Supports multiple secret management backends
 */

const AWS = require('aws-sdk');
const { SecretManagerServiceClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor(options = {}) {
    this.provider = options.provider || process.env.SECRETS_PROVIDER || 'aws';
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes default
    this.initialized = false;
  }

  /**
   * Initialize the secrets manager client
   */
  async initialize() {
    if (this.initialized) return;

    switch (this.provider) {
      case 'aws':
        this.client = new SecretManagerServiceClient({ 
          region: this.region,
          // Use IAM roles instead of access keys
          credentials: undefined // Let AWS SDK handle credential chain
        });
        break;

      case 'vault':
        // HashiCorp Vault implementation
        const vault = require('node-vault');
        this.client = vault({
          apiVersion: 'v1',
          endpoint: process.env.VAULT_ADDR,
          token: process.env.VAULT_TOKEN, // Use AppRole in production
        });
        break;

      case 'azure':
        // Azure Key Vault implementation
        const { SecretClient } = require('@azure/keyvault-secrets');
        const { DefaultAzureCredential } = require('@azure/identity');
        this.client = new SecretClient(
          process.env.AZURE_KEYVAULT_URI,
          new DefaultAzureCredential()
        );
        break;

      case 'gcp':
        // Google Cloud Secret Manager
        const { SecretManagerServiceClient: GCPSecretManager } = require('@google-cloud/secret-manager');
        this.client = new GCPSecretManager();
        break;

      default:
        throw new Error(`Unsupported secrets provider: ${this.provider}`);
    }

    this.initialized = true;
  }

  /**
   * Get a secret with caching and error handling
   */
  async getSecret(secretName, options = {}) {
    await this.initialize();

    // Check cache first
    if (!options.skipCache) {
      const cached = this.cache.get(secretName);
      if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      let secretValue;

      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAWSSecret(secretName);
          break;
        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;
        case 'azure':
          secretValue = await this.getAzureSecret(secretName);
          break;
        case 'gcp':
          secretValue = await this.getGCPSecret(secretName);
          break;
      }

      // Cache the secret
      if (!options.skipCache) {
        this.cache.set(secretName, {
          value: secretValue,
          timestamp: Date.now()
        });
      }

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);

      // Return fallback if provided
      if (options.fallback !== undefined) {
        console.warn(`Using fallback value for ${secretName}`);
        return options.fallback;
      }

      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  /**
   * AWS Secrets Manager implementation
   */
  async getAWSSecret(secretName) {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await this.client.send(command);

    if (response.SecretString) {
      try {
        return JSON.parse(response.SecretString);
      } catch {
        return response.SecretString;
      }
    }

    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    throw new Error('Secret value not found');
  }

  /**
   * HashiCorp Vault implementation
   */
  async getVaultSecret(secretPath) {
    const result = await this.client.read(secretPath);
    return result.data;
  }

  /**
   * Azure Key Vault implementation
   */
  async getAzureSecret(secretName) {
    const secret = await this.client.getSecret(secretName);
    try {
      return JSON.parse(secret.value);
    } catch {
      return secret.value;
    }
  }

  /**
   * Google Cloud Secret Manager implementation
   */
  async getGCPSecret(secretName) {
    const projectId = process.env.GCP_PROJECT_ID;
    const name = `projects/${projectId}/secrets/${secretName}/versions/latest`;
    const [version] = await this.client.accessSecretVersion({ name });
    const payload = version.payload.data.toString();

    try {
      return JSON.parse(payload);
    } catch {
      return payload;
    }
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => this.getSecret(name));
    return Promise.all(promises);
  }

  /**
   * Clear cache (useful for testing or forced refresh)
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }

  /**
   * Rotate secret (update to new version)
   */
  async rotateSecret(secretName) {
    this.clearCache(secretName);
    return await this.getSecret(secretName, { skipCache: true });
  }
}

