/**
 * Secure Configuration Loader
 * Loads secrets from secrets manager instead of .env files
 */

const { getSecretsManager } = require('./secrets-manager');

class ConfigLoader {
  constructor() {
    this.config = {};
    this.loaded = false;
    this.secretsManager = getSecretsManager();
  }

  /**
   * Load all application secrets
   */
  async loadSecrets() {
    if (this.loaded) {
      return this.config;
    }

    try {
      console.log('Loading secrets from secrets manager...');

      // Define which secrets to load based on environment
      const secretsToLoad = this.getRequiredSecrets();

      // Load all secrets in parallel
      const secretPromises = Object.entries(secretsToLoad).map(
        async ([key, secretName]) => {
          try {
            const value = await this.secretsManager.getSecret(secretName);
            return { key, value };
          } catch (error) {
            console.error(`Failed to load secret ${key}:`, error.message);

            // Check if secret is required or optional
            if (secretsToLoad[key].required !== false) {
              throw error;
            }
            return { key, value: null };
          }
        }
      );

      const results = await Promise.all(secretPromises);

      // Build config object
      results.forEach(({ key, value }) => {
        if (typeof value === 'object' && value !== null) {
          // If secret is JSON, spread it
          Object.assign(this.config, value);
        } else {
          this.config[key] = value;
        }
      });

      // Validate required secrets are present
      this.validateConfig();

      this.loaded = true;
      console.log('Secrets loaded successfully');

      return this.config;
    } catch (error) {
      console.error('Failed to load secrets:', error);
      throw new Error('Configuration loading failed');
    }
  }

  /**
   * Get list of required secrets based on environment
   */
  getRequiredSecrets() {
    const env = process.env.NODE_ENV || 'development';
    const appName = process.env.APP_NAME || 'myapp';

    // Secret naming convention: {env}/{app-name}/{secret-name}
    const prefix = `${env}/${appName}`;

    return {
      // Database secrets
      DATABASE_URL: `${prefix}/database/url`,
      DB_PASSWORD: `${prefix}/database/password`,

      // JWT secrets
      JWT_SECRET: `${prefix}/auth/jwt-secret`,
      JWT_REFRESH_SECRET: `${prefix}/auth/jwt-refresh-secret`,

      // AWS credentials (if not using IAM roles)
      AWS_ACCESS_KEY_ID: {
        name: `${prefix}/aws/access-key-id`,
        required: false // Optional if using IAM roles
      },
      AWS_SECRET_ACCESS_KEY: {
        name: `${prefix}/aws/secret-access-key`,
        required: false
      },

      // Third-party API keys
      ANTHROPIC_API_KEY: `${prefix}/apis/anthropic`,
      STRIPE_SECRET_KEY: `${prefix}/apis/stripe`,
      LOGFIRE_TOKEN: `${prefix}/apis/logfire`,

      // Encryption keys
      ENCRYPTION_KEY: `${prefix}/crypto/encryption-key`,

      // Session secrets
      SESSION_SECRET: `${prefix}/auth/session-secret`,
    };
  }

  /**
   * Validate that all required configuration is present
   */
  validateConfig() {
    const required = [
      'DATABASE_URL',
      'JWT_SECRET',
    ];

    const missing = required.filter(key => !this.config[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required configuration: ${missing.join(', ')}`);
    }
  }

  /**
   * Get a configuration value
   */
  get(key, defaultValue = undefined) {
    return this.config[key] || defaultValue;
  }

  /**
   * Check if a configuration key exists
   */
  has(key) {
    return key in this.config;
  }

  /**
   * Reload secrets (useful for rotation)
   */
  async reload() {
    this.loaded = false;
    this.config = {};
    this.secretsManager.clearCache();
    return await this.loadSecrets();
  }
}

// Singleton instance
let instance = null;

/**
 * Get or create config loader instance
 */
function getConfigLoader() {
  if (!instance) {
    instance = new ConfigLoader();
  }
  return instance;
}

module.exports = {
  ConfigLoader,
  getConfigLoader
};

/**
 * Secure app.js with proper secrets management
 * NO hardcoded secrets or .env files with sensitive data
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { getConfigLoader } = require('./config/config-loader');

const app = express();

// Global configuration
let config;

/**
 * Initialize application with secrets from secrets manager
 */
async function initializeApp() {
  try {
    // Load secrets from secrets manager
    const configLoader = getConfigLoader();
    config = await configLoader.loadSecrets();

    console.log('Application configuration loaded securely');

    // Verify critical secrets are present
    if (!config.JWT_SECRET || !config.DATABASE_URL) {
      throw new Error('Critical secrets missing from secrets manager');
    }

    return true;
  } catch (error) {
    console.error('Failed to initialize application:', error);
    console.error('Ensure secrets are properly configured in your secrets manager');
    process.exit(1);
  }
}

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));

// CORS configuration - get allowed origins from config
app.use(cors({
  origin: function (origin, callback) {
    const whitelist = config?.ALLOWED_ORIGINS?.split(',') || [];
    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
}));

// Body parsing with limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests, please try again later.',
});

app.use(limiter);

/**
 * Authentication middleware using JWT secret from secrets manager
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Use JWT secret from secrets manager
  jwt.verify(token, config.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Routes
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    secrets_loaded: !!config
  });
});

app.get('/users', authenticateToken, (req, res) => {
  // Database connection would use config.DATABASE_URL
  // AWS operations would use config.AWS_ACCESS_KEY_ID, etc.

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    path: req.path,
    method: req.method,
  });

  // Never expose secret values in error messages
  const sanitizedError = err.message.replace(
    /sk-[a-zA-Z0-9_-]+|AKIA[A-Z0-9]+|postgres:\/\/[^@]+@/g,
    '[REDACTED]'
  );

  if (process.env.NODE_ENV === 'production') {
    return res.status(err.status || 500).json({ 
      error: 'Internal Server Error' 
    });
  }

  res.status(err.status || 500).json({ 
    error: sanitizedError
  });
});

/**
 * Start server only after secrets are loaded
 */
async function startServer() {
  await initializeApp();

  const PORT = process.env.PORT || 3000;
  const HOST = process.env.HOST || '0.0.0.0';

  const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log('✓ Secrets loaded from secrets manager (not .env files)');
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  // Handle secret rotation
  process.on('SIGHUP', async () => {
    console.log('SIGHUP received: reloading secrets');
    try {
      const configLoader = getConfigLoader();
      config = await configLoader.reload();
      console.log('Secrets reloaded successfully');
    } catch (error) {
      console.error('Failed to reload secrets:', error);
    }
  });
}

// Start the application
if (require.main === module) {
  startServer().catch(error => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = app;

/**
 * Secret Scanner - Detect secrets in code and logs
 * Run this before commits to prevent secret leaks
 */

const fs = require('fs').promises;
const path = require('path');

class SecretScanner {
  constructor() {
    // Regex patterns for common secret types
    this.patterns = {
      awsAccessKey: {
        pattern: /AKIA[0-9A-Z]{16}/g,
        name: 'AWS Access Key',
        severity: 'CRITICAL'
      },
      awsSecretKey: {
        pattern: /aws_secret[_-]?access[_-]?key[\s]*=[\s]*['"]?([A-Za-z0-9/+=]{40})['"]?/gi,
        name: 'AWS Secret Key',
        severity: 'CRITICAL'
      },
      privateKey: {
        pattern: /-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----/g,
        name: 'Private Key',
        severity: 'CRITICAL'
      },
      genericApiKey: {
        pattern: /['"]?api[_-]?key['"]?\s*[:=]\s*['"]([A-Za-z0-9_\-]{20,})['"]?/gi,
        name: 'Generic API Key',
        severity: 'HIGH'
      },
      anthropicKey: {
        pattern: /sk-ant-[a-zA-Z0-9\-]{95}/g,
        name: 'Anthropic API Key',
        severity: 'CRITICAL'
      },
      stripeKey: {
        pattern: /sk-live-[0-9a-zA-Z]{24,}/g,
        name: 'Stripe Live Secret Key',
        severity: 'CRITICAL'
      },
      jwtSecret: {
        pattern: /jwt[_-]?secret[\s]*=[\s]*['"]([A-Za-z0-9_\-+/=]{20,})['"]?/gi,
        name: 'JWT Secret',
        severity: 'HIGH'
      },
      databaseUrl: {
        pattern: /(?:postgres|mysql|mongodb):\/\/[^:]+:[^@]+@[^\/]+/gi,
        name: 'Database URL with Credentials',
        severity: 'CRITICAL'
      },
      password: {
        pattern: /['"]?password['"]?\s*[:=]\s*['"]([^'"]{8,})['"]?/gi,
        name: 'Password',
        severity: 'HIGH'
      },
      bearerToken: {
        pattern: /Bearer\s+[A-Za-z0-9\-._~+\/]+=*/g,
        name: 'Bearer Token',
        severity: 'MEDIUM'
      }
    };

    this.excludePatterns = [
      /node_modules/,
      /\.git/,
      /\.env\.example/,
      /package-lock\.json/,
      /yarn\.lock/,
      /dist/,
      /build/,
      /coverage/
    ];
  }

  /**
   * Scan a file for secrets
   */
  async scanFile(filePath) {
    const findings = [];

    try {
      const content = await fs.readFile(filePath, 'utf-8');
      const lines = content.split('\n');

      for (const [key, config] of Object.entries(this.patterns)) {
        const matches = content.matchAll(config.pattern);

        for (const match of matches) {
          const lineNumber = this.getLineNumber(content, match.index);
          const line = lines[lineNumber - 1].trim();

          // Skip if it looks like a placeholder or example
          if (this.isLikelyPlaceholder(match[0])) {
            continue;
          }

          findings.push({
            file: filePath,
            line: lineNumber,
            type: config.name,
            severity: config.severity,
            preview: this.getPreview(line),
            match: match[0].substring(0, 20) + '...'
          });
        }
      }
    } catch (error) {
      if (error.code !== 'ENOENT') {
        console.error(`Error scanning ${filePath}:`, error.message);
      }
    }

    return findings;
  }

  /**
   * Scan a directory recursively
   */
  async scanDirectory(dirPath, options = {}) {
    const { recursive = true, extensions = ['.js', '.ts', '.json', '.env', '.yml', '.yaml', '.txt'] } = options;
    let allFindings = [];

    try {
      const entries = await fs.readdir(dirPath, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dirPath, entry.name);

        // Skip excluded paths
        if (this.shouldExclude(fullPath)) {
          continue;
        }

        if (entry.isDirectory() && recursive) {
          const subFindings = await this.scanDirectory(fullPath, options);
          allFindings = allFindings.concat(subFindings);
        } else if (entry.isFile()) {
          const ext = path.extname(entry.name);
          if (extensions.length === 0 || extensions.includes(ext)) {
            const findings = await this.scanFile(fullPath);
            allFindings = allFindings.concat(findings);
          }
        }
      }
    } catch (error) {
      console.error(`Error scanning directory ${dirPath}:`, error.message);
    }

    return allFindings;
  }

  /**
   * Check if path should be excluded
   */
  shouldExclude(filePath) {
    return this.excludePatterns.some(pattern => pattern.test(filePath));
  }

  /**
   * Check if match is likely a placeholder
   */
  isLikelyPlaceholder(value) {
    const placeholders = [
      /YOUR[_-]?KEY/i,
      /REPLACE[_-]?ME/i,
      /EXAMPLE/i,
      /PLACEHOLDER/i,
      /XXX+/i,
      /\*\*\*+/,
      /dummy/i,
      /test[_-]?key/i,
      /CANARY/i  // Our test credentials
    ];

    return placeholders.some(pattern => pattern.test(value));
  }

  /**
   * Get line number from index
   */
  getLineNumber(content, index) {
    return content.substring(0, index).split('\n').length;
  }

  /**
   * Get preview of the line (truncated)
   */
  getPreview(line, maxLength = 80) {
    if (line.length <= maxLength) {
      return line;
    }
    return line.substring(0, maxLength) + '...';
  }

  /**
   * Generate report
   */
  generateReport(findings) {
    if (findings.length === 0) {
      return {
        summary: '✅ No secrets detected',
        critical: 0,
        high: 0,
        medium: 0,
        findings: []
      };
    }

    const groupedBySeverity = {
      CRITICAL: findings.filter(f => f.severity === 'CRITICAL'),
      HIGH: findings.filter(f => f.severity === 'HIGH'),
      MEDIUM: findings.filter(f => f.severity === 'MEDIUM')
    };

    return {
      summary: `🚨 ${findings.length} potential secret(s) detected!`,
      critical: groupedBySeverity.CRITICAL.length,
      high: groupedBySeverity.HIGH.length,
      medium: groupedBySeverity.MEDIUM.length,
      findings: findings
    };
  }

  /**
   * Print report to console
   */
  printReport(report) {
    console.log('\n' + '='.repeat(80));
    console.log('SECRET SCANNER REPORT');
    console.log('='.repeat(80) + '\n');

    console.log(report.summary);

    if (report.findings.length > 0) {
      console.log(`\nCRITICAL: ${report.critical} | HIGH: ${report.high} | MEDIUM: ${report.medium}\n`);

      // Group by file
      const byFile = {};
      for (const finding of report.findings) {
        if (!byFile[finding.file]) {
          byFile[finding.file] = [];
        }
        byFile[finding.file].push(finding);
      }

      for (const [file, findings] of Object.entries(byFile)) {
        console.log(`\n📁 ${file}`);
        for (const finding of findings) {
          const severityIcon = {
            CRITICAL: '🔴',
            HIGH: '🟠',
            MEDIUM: '🟡'
          }[finding.severity];

          console.log(`  ${severityIcon} Line ${finding.line}: ${finding.type}`);
          console.log(`     Preview: ${finding.preview}`);
        }
      }

      console.log('\n' + '='.repeat(80));
      console.log('⚠️  ACTION REQUIRED:');
      console.log('1. Remove all secrets from code');
      console.log('2. Move secrets to secrets manager');
      console.log('3. Rotate any exposed secrets');
      console.log('4. Review git history for leaked secrets');
      console.log('='.repeat(80) + '\n');
    } else {
      console.log('\n' + '='.repeat(80) + '\n');
    }

    return report.findings.length === 0 ? 0 : 1;
  }
}

// CLI interface
async function main() {
  const scanner = new SecretScanner();
  const targetPath = process.argv[2] || '.';

  console.log(`Scanning ${targetPath} for secrets...\n`);

  const findings = await scanner.scanDirectory(targetPath);
  const report = scanner.generateReport(findings);
  const exitCode = scanner.printReport(report);

  process.exit(exitCode);
}

// Run if called directly
if (require.main === module) {
  main().catch(error => {
    console.error('Scanner error:', error);
    process.exit(1);
  });
}

module.exports = { SecretScanner };

