### Solution 1: Implement Proper Secrets Manager (RECOMMENDED)

Create a `secrets.js` module:

```javascript
// secrets.js
const AWS = require('aws-sdk');
const { SecretManagerServiceClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Load secrets from AWS Secrets Manager
   */
  async loadFromAWS(secretName, region = 'us-east-1') {
    const cacheKey = `aws:${secretName}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.value;
    }

    try {
      const client = new SecretManagerServiceClient({ region });
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      const secret = JSON.parse(response.SecretString);

      this.cache.set(cacheKey, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error('Error loading secret from AWS:', error);
      throw new Error('Failed to load secrets');
    }
  }

  /**
   * Load secrets from Azure Key Vault
   */
  async loadFromAzure(vaultUrl, secretName) {
    const { DefaultAzureCredential } = require('@azure/identity');
    const { SecretClient } = require('@azure/keyvault-secrets');

    const cacheKey = `azure:${secretName}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.value;
    }

    try {
      const credential = new DefaultAzureCredential();
      const client = new SecretClient(vaultUrl, credential);
      const secret = await client.getSecret(secretName);

      this.cache.set(cacheKey, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error('Error loading secret from Azure:', error);
      throw new Error('Failed to load secrets');
    }
  }

  /**
   * Load secrets from HashiCorp Vault
   */
  async loadFromVault(vaultAddr, token, path) {
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: vaultAddr,
      token: token
    });

    const cacheKey = `vault:${path}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.value;
    }

    try {
      const result = await vault.read(path);
      const secrets = result.data;

      this.cache.set(cacheKey, {
        value: secrets,
        timestamp: Date.now()
      });

      return secrets;
    } catch (error) {
      console.error('Error loading secret from Vault:', error);
      throw new Error('Failed to load secrets');
    }
  }

  /**
   * Fallback to environment variables (only for local dev)
   */
  loadFromEnv(keys) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Environment variables not allowed in production');
    }

    const secrets = {};
    const missing = [];

    keys.forEach(key => {
      if (process.env[key]) {
        secrets[key] = process.env[key];
      } else {
        missing.push(key);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }

    return secrets;
  }

  /**
   * Clear sensitive data from cache
   */
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;
```

