#!/bin/bash
# Pre-commit hook to prevent committing secrets

RED='\033[0;31m'
NC='\033[0m' # No Color

# Patterns that indicate secrets
PATTERNS=(
  'AWS_SECRET_ACCESS_KEY'
  'AWS_ACCESS_KEY_ID'
  'ANTHROPIC_API_KEY'
  'STRIPE_SECRET_KEY'
  'sk-live-'
  'sk-test-'
  'password\s*=\s*["\047].*["\047]'
  'api[_-]?key\s*=\s*["\047].*["\047]'
  'secret\s*=\s*["\047].*["\047]'
  'token\s*=\s*["\047].*["\047]'
  'BEGIN.*PRIVATE KEY'
)

echo "🔍 Scanning for secrets..."

FOUND=0
for pattern in "${PATTERNS[@]}"; do
  if git diff --cached --name-only | xargs grep -iE "$pattern" 2>/dev/null; then
    echo -e "${RED}❌ Potential secret found matching: $pattern${NC}"
    FOUND=1
  fi
done

if [ $FOUND -eq 1 ]; then
  echo -e "${RED}"
  echo "╔════════════════════════════════════════════════════════════╗"
  echo "║  COMMIT BLOCKED: Potential secrets detected!              ║"
  echo "║                                                            ║"
  echo "║  Please remove secrets and use a secrets manager instead. ║"
  echo "╚════════════════════════════════════════════════════════════╝"
  echo -e "${NC}"
  exit 1
fi

echo "✓ No secrets detected"
exit 0
```

