/**
 * Secure Secrets Manager
 * Supports multiple backends: AWS Secrets Manager, Azure Key Vault, HashiCorp Vault, GCP Secret Manager
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class SecretsManager {
  constructor(config = {}) {
    this.provider = config.provider || process.env.SECRETS_PROVIDER || 'env';
    this.region = config.region || process.env.AWS_REGION || 'us-east-1';
    this.cache = new Map();
    this.cacheTTL = config.cacheTTL || 300000; // 5 minutes default

    this.initializeProvider();
  }

  initializeProvider() {
    switch (this.provider) {
      case 'aws':
        this.client = new SecretsManagerClient({ region: this.region });
        break;
      case 'gcp':
        this.client = new SecretManagerServiceClient();
        break;
      case 'azure':
        // Azure Key Vault setup
        const { SecretClient } = require('@azure/keyvault-secrets');
        const { DefaultAzureCredential } = require('@azure/identity');
        const vaultUrl = process.env.AZURE_KEY_VAULT_URL;
        if (vaultUrl) {
          this.client = new SecretClient(vaultUrl, new DefaultAzureCredential());
        }
        break;
      case 'vault':
        // HashiCorp Vault setup
        const vault = require('node-vault');
        this.client = vault({
          endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
          token: process.env.VAULT_TOKEN
        });
        break;
      case 'env':
      default:
        console.warn('⚠️  Using environment variables for secrets. Not recommended for production.');
        break;
    }
  }

  /**
   * Get secret from appropriate provider with caching
   */
  async getSecret(secretName, options = {}) {
    const cacheKey = `${this.provider}:${secretName}`;
    const cached = this.cache.get(cacheKey);

    // Return cached value if still valid
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    let secretValue;

    try {
      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAWSSecret(secretName);
          break;
        case 'gcp':
          secretValue = await this.getGCPSecret(secretName);
          break;
        case 'azure':
          secretValue = await this.getAzureSecret(secretName);
          break;
        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;
        case 'env':
        default:
          secretValue = process.env[secretName];
          if (!secretValue && options.required) {
            throw new Error(`Required secret ${secretName} not found in environment`);
          }
          break;
      }

      // Cache the secret
      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);

      // Fallback to environment variable in development only
      if (process.env.NODE_ENV === 'development') {
        console.warn(`⚠️  Falling back to environment variable for ${secretName}`);
        return process.env[secretName];
      }

      throw error;
    }
  }

  /**
   * AWS Secrets Manager
   */
  async getAWSSecret(secretName) {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await this.client.send(command);

    if (response.SecretString) {
      // Handle JSON secrets
      try {
        return JSON.parse(response.SecretString);
      } catch {
        return response.SecretString;
      }
    } else {
      // Handle binary secrets
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }
  }

  /**
   * GCP Secret Manager
   */
  async getGCPSecret(secretName) {
    const projectId = process.env.GCP_PROJECT_ID;
    const name = `projects/${projectId}/secrets/${secretName}/versions/latest`;

    const [version] = await this.client.accessSecretVersion({ name });
    return version.payload.data.toString('utf8');
  }

  /**
   * Azure Key Vault
   */
  async getAzureSecret(secretName) {
    const secret = await this.client.getSecret(secretName);
    return secret.value;
  }

  /**
   * HashiCorp Vault
   */
  async getVaultSecret(secretName) {
    const path = process.env.VAULT_SECRET_PATH || 'secret/data/app';
    const result = await this.client.read(`${path}/${secretName}`);
    return result.data.data;
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretNames) {
    const secrets = {};
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }

  /**
   * Clear cache (useful for secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Validate that all required secrets are available
   */
  async validateSecrets(requiredSecrets) {
    const missing = [];

    for (const secretName of requiredSecrets) {
      try {
        const value = await this.getSecret(secretName, { required: true });
        if (!value) {
          missing.push(secretName);
        }
      } catch (error) {
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log('✅ All required secrets validated');
    return true;
  }
}

// Singleton instance
let instance = null;

/**
 * Get or create secrets manager instance
 */
function getSecretsManager(config) {
  if (!instance) {
    instance = new SecretsManager(config);
  }
  return instance;
}

module.exports = {
  SecretsManager,
  getSecretsManager
};

/**
 * Secure Configuration Manager
 * Loads secrets from appropriate sources based on environment
 */

require('dotenv').config();
const { getSecretsManager } = require('./secrets-manager');

class Config {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.useSecretsManager = process.env.USE_SECRETS_MANAGER === 'true';
    this.secretsManager = null;
    this.initialized = false;
  }

  /**
   * Initialize configuration and load secrets
   */
  async initialize() {
    if (this.initialized) {
      return;
    }

    console.log(`🔧 Initializing configuration for ${this.env} environment`);

    // Initialize secrets manager if enabled
