  }
});

// Protected users endpoint
app.get('/users', 
  (req, res, next) => {
    if (appConfig) {
      createRateLimiter()(req, res, next);
    } else {
      next();
    }
  },
  authenticateToken,
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('search').optional().trim().escape()
  ],
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Return sanitized data
    const sanitized = users.map(u => sanitizeUser(u, !!req.user));
    res.json(sanitized);
  }
);

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  const isDevelopment = process.env.NODE_ENV === 'development';

  // Never expose sensitive information in errors
  const sanitizedMessage = err.message?.includes('secret') || err.message?.includes('password')
    ? 'Configuration error'
    : err.message;

  res.status(err.status || 500).json({
    error: isDevelopment ? sanitizedMessage : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

/**
 * Start server with secure configuration
 */
async function startServer() {
  // Initialize configuration first
  await initializeApp();

  const PORT = appConfig.port;
  const server = app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT} in ${appConfig.env} mode`);
    console.log(`🔒 Security features enabled:`);
    console.log(`   - Helmet (security headers)`);
    console.log(`   - CORS protection`);
    console.log(`   - Rate limiting`);
    console.log(`   - Input validation`);
    console.log(`   - JWT authentication`);
    if (process.env.USE_SECRETS_MANAGER === 'true') {
      console.log(`   - Secrets Manager (${process.env.SECRETS_PROVIDER || 'aws'})`);
    }
  });

  // Graceful shutdown
  const shutdown = async (signal) => {
    console.log(`\n${signal} signal received: closing HTTP server`);
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  return server;
}

// Start server only if not being required as a module
if (require.main === module) {
  startServer().catch(error => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = { app, startServer };

