/**
 * Secure Secrets Management Module
 * Uses AWS Secrets Manager in production, dotenv in development
 */

const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes

    if (this.environment === 'production') {
      this.secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    } else {
      // Only load dotenv in non-production
      require('dotenv').config();
    }
  }

  /**
   * Get secret from AWS Secrets Manager with caching
   * @param {string} secretName - Name of the secret
   * @returns {Promise<object>} - Parsed secret value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      if (this.environment === 'production') {
        const data = await this.secretsManager.getSecretValue({ 
          SecretId: secretName 
        }).promise();

        let secret;
        if (data.SecretString) {
          secret = JSON.parse(data.SecretString);
        } else {
          // Binary secret
          const buff = Buffer.from(data.SecretBinary, 'base64');
          secret = buff.toString('ascii');
        }

        // Cache the secret
        this.cache.set(secretName, {
          value: secret,
          timestamp: Date.now()
        });

        return secret;
      } else {
        // Development: return from environment variables
        console.warn(`[DEV MODE] Loading secret ${secretName} from environment`);
        return this.getFromEnv(secretName);
      }
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get secret from environment variables (development only)
   * @param {string} secretName - Name of the secret
   * @returns {object} - Secret values from env
   */
  getFromEnv(secretName) {
    // Map secret names to environment variables
    const envMapping = {
      'app/database': {
        url: process.env.DATABASE_URL,
        username: process.env.DB_USERNAME,
        password: process.env.DB_PASSWORD
      },
      'app/aws': {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      },
      'app/api-keys': {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      },
      'app/jwt': {
        secret: process.env.JWT_SECRET
      }
    };

    return envMapping[secretName] || {};
  }

  /**
   * Initialize all required secrets on app startup
   * Validates that all secrets are accessible
   */
  async initialize() {
    const requiredSecrets = [
      'app/database',
      'app/jwt',
      'app/api-keys'
    ];

    console.log('Initializing secrets...');

    for (const secretName of requiredSecrets) {
      try {
        await this.getSecret(secretName);
        console.log(`✓ Secret ${secretName} loaded successfully`);
      } catch (error) {
        console.error(`✗ Failed to load secret ${secretName}`);
        throw error;
      }
    }

    console.log('All secrets initialized successfully');
  }

  /**
   * Clear the secrets cache (call periodically or on-demand)
   */
  clearCache() {
    this.cache.clear();
    console.log('Secrets cache cleared');
  }

  /**
   * Get a single environment variable (for non-sensitive config)
   * @param {string} key - Environment variable name
   * @param {string} defaultValue - Default value if not found
   * @returns {string} - Environment variable value
   */
  getEnvVar(key, defaultValue = null) {
    const value = process.env[key];
    if (!value && defaultValue === null) {
      throw new Error(`Required environment variable ${key} is not set`);
    }
    return value || defaultValue;
  }
}

// Export singleton instance
module.exports = new SecretsManager();

/**
 * HashiCorp Vault Secrets Manager
 * Alternative to AWS Secrets Manager
 */

const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';

    if (this.environment === 'production') {
      this.client = vault({
        apiVersion: 'v1',
        endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
        token: process.env.VAULT_TOKEN
      });
    } else {
      require('dotenv').config();
    }

    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  /**
   * Get secret from Vault
   * @param {string} path - Path to secret in Vault
   * @returns {Promise<object>} - Secret data
   */
  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      if (this.environment === 'production') {
        const result = await this.client.read(path);
        const secret = result.data.data || result.data;

        this.cache.set(path, {
          value: secret,
          timestamp: Date.now()
        });

        return secret;
      } else {
        console.warn(`[DEV MODE] Loading secret from environment`);
        return this.getFromEnv(path);
      }
    } catch (error) {
      console.error(`Error retrieving secret from ${path}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${path}`);
    }
  }

  /**
   * Get database credentials from Vault's dynamic secrets
   * Vault can generate short-lived database credentials
   */
  async getDatabaseCredentials() {
    try {
      const result = await this.client.read('database/creds/app-role');
      return {
        username: result.data.username,
        password: result.data.password,
        lease_id: result.data.lease_id,
        lease_duration: result.data.lease_duration
      };
    } catch (error) {
      console.error('Error getting database credentials:', error.message);
      throw error;
    }
  }

  /**
   * Renew a lease (for dynamic secrets)
   */
  async renewLease(leaseId, increment = 3600) {
    try {
      return await this.client.renew({ lease_id: leaseId, increment });
    } catch (error) {
      console.error('Error renewing lease:', error.message);
      throw error;
    }
  }

  getFromEnv(path) {
    // Development fallback
    return {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY
    };
  }
}

module.exports = new VaultSecretsManager();

/**
 * Azure Key Vault Secrets Manager
 * For Azure-hosted applications
 */

const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureSecretsManager {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';

    if (this.environment === 'production') {
      const vaultName = process.env.AZURE_KEY_VAULT_NAME;
      if (!vaultName) {
        throw new Error('AZURE_KEY_VAULT_NAME environment variable is required');
      }

      const url = `https://${vaultName}.vault.azure.net`;
      const credential = new DefaultAzureCredential();
      this.client = new SecretClient(url, credential);
    } else {
      require('dotenv').config();
    }

    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  /**
   * Get secret from Azure Key Vault
   * @param {string} secretName - Name of the secret
   * @returns {Promise<string>} - Secret value
   */
  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      if (this.environment === 'production') {
        const secret = await this.client.getSecret(secretName);

        this.cache.set(secretName, {
          value: secret.value,
          timestamp: Date.now()
        });

        return secret.value;
      } else {
        console.warn(`[DEV MODE] Loading secret ${secretName} from environment`);
        return process.env[secretName.toUpperCase().replace(/-/g, '_')];
      }
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>} - Object with secret names as keys
   */
  async getSecrets(secretNames) {
    const secrets = {};

    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }

    return secrets;
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new AzureSecretsManager();

