    config.server.port = process.env.PORT || 3000;
    config.server.env = process.env.NODE_ENV || 'development';
    config.server.allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

    logger.info('Configuration loaded successfully');

  } catch (error) {
    logger.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

/**
 * Setup Express middleware
 */
function setupMiddleware() {
  // Security middleware
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", 'data:', 'https:'],
      },
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    },
  }));

  // CORS configuration
  const corsOptions = {
    origin: config.server.allowedOrigins,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400,
  };
  app.use(cors(corsOptions));

  // Body parsing with size limits
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ extended: true, limit: '10kb' }));

  // Data sanitization
  app.use(mongoSanitize());
  app.use(xss());

  // Rate limiting
  const generalLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(generalLimiter);

  // HTTPS enforcement in production
  if (config.server.env === 'production') {
    app.use((req, res, next) => {
      if (req.header('x-forwarded-proto') !== 'https') {
        return res.redirect(`https://${req.header('host')}${req.url}`);
      }
      next();
    });
  }

  // Request logging (exclude sensitive headers)
  app.use((req, res, next) => {
    const logData = {
      method: req.method,
      url: req.url,
      ip: req.ip,
      userAgent: req.get('user-agent')
    };
    logger.info('Request received', logData);
    next();
  });
}

/**
 * Authentication middleware
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Authentication required' });
  }

  jwt.verify(token, config.jwt.secret, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}`, { error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

/**
 * Authorization middleware
 */
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to ${req.path}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

/**
 * Data sanitization helper
 */
const sanitizeUserData = (user, requesterRole, requesterId) => {
  const safeData = {
    id: user.id,
    name: user.name
  };

  // Only expose email to admins or the user themselves
  if (requesterRole === 'admin' || requesterId === user.id) {
    safeData.email = user.email;
  }

  return safeData;
};

/**
 * Setup routes
 */
function setupRoutes() {
  // Health check endpoint (no auth required)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: config.server.env 
    });
  });

  // Secure users endpoint
  app.get('/users', 
    authenticateToken,
    authorize('admin', 'user'),
    (req, res) => {
      try {
        const users = [
          { id: 1, name: 'Alice', email: 'alice@example.com' },
          { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        const sanitized = users.map(user => 
          sanitizeUserData(user, req.user.role, req.user.id)
        );

        logger.info(`User list accessed by user ${req.user.id}`);
        res.json(sanitized);
      } catch (error) {
        logger.error('Error fetching users:', error);
        res.status(500).json({ error: 'Failed to fetch users' });
      }
    }
  );

  app.get('/users/:id',
    authenticateToken,
    param('id').isInt().withMessage('ID must be an integer'),
    (req, res) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json(sanitizeUserData(user, req.user.role, req.user.id));
    }
  );

  // 404 handler
  app.use((req, res, next) => {
    logger.warn(`404 - Not found: ${req.method} ${req.url} from ${req.ip}`);
    res.status(404).json({ error: 'Resource not found' });
  });

  // Global error handler (must be last)
  app.use((err, req, res, next) => {
    logger.error({
      message: err.message,
      stack: err.stack,
      url: req.url,
      method: req.method,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });

    const isDevelopment = config.server.env === 'development';

    res.status(err.status || 500).json({
      error: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack }),
    });
  });
}

/**
 * Start the server
 */
async function startServer() {
  await initializeApp();
  setupMiddleware();
  setupRoutes();

  const server = app.listen(config.server.port, () => {
    logger.info(`Server running on port ${config.server.port} in ${config.server.env} mode`);
    console.log(`✓ Server running on port ${config.server.port}`);
  });

  // Graceful shutdown
  const shutdown = async () => {
    logger.info('Shutdown signal received: closing HTTP server');

    server.close(() => {
      logger.info('HTTP server closed');

      // Clear secrets cache
      if (secretsManager.clearCache) {
        secretsManager.clearCache();
        logger.info('Secrets cache cleared');
      }

      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      logger.error('Could not close connections in time, forcefully shutting down');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);

  return server;
}

// Start the application
if (require.main === module) {
  startServer().catch(error => {
    logger.error('Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = { app, startServer, config };

