// Secure Application Implementation
// Addresses OWASP Top 10 vulnerabilities

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// ===== CONFIGURATION =====
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName] && NODE_ENV === 'production') {
    console.error(`Error: ${varName} environment variable is required in production`);
    process.exit(1);
  }
});

// ===== LOGGING SETUP =====
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ===== SECURITY MIDDLEWARE =====

// 1. Security Headers (Helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. CORS Configuration
const corsOptions = {
  origin: function (origin, callback) {
    const whitelist = process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',')
      : ['http://localhost:3000'];

    // Allow requests with no origin (like mobile apps or curl)
    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// 3. Body Parsing with Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. HTTP Request Logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// 5. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests, please try again later.'
    });
  }
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many attempts, please try again later.',
});

app.use('/api/', generalLimiter);

// 6. Request Logging Middleware
app.use((req, res, next) => {
  logger.info('Incoming request', {
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// ===== AUTHENTICATION MIDDLEWARE =====
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret-key', (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Optional authentication (doesn't fail if no token)
const optionalAuth = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (token) {
    jwt.verify(token, process.env.JWT_SECRET || 'dev-secret-key', (err, user) => {
      if (!err) {
        req.user = user;
      }
    });
  }
  next();
};

// ===== VALIDATION MIDDLEWARE =====
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { errors: errors.array(), ip: req.ip });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ===== HELPER FUNCTIONS =====
const maskEmail = (email) => {
  if (!email) return '';
  const [local, domain] = email.split('@');
  if (!local || !domain) return email;
  return `${local.substring(0, Math.min(2, local.length))}***@${domain}`;
};

const sanitizeUserData = (user, hasFullAccess = false) => {
  return {
    id: user.id,
    name: user.name,
    email: hasFullAccess ? user.email : maskEmail(user.email)
  };
};

// ===== ROUTES =====

// Health check endpoint (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Users endpoint (protected)
app.get('/users', strictLimiter, optionalAuth, (req, res) => {
  // Mock user data (in production, this would come from a database)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Check if user has admin privileges
  const hasFullAccess = req.user && req.user.role === 'admin';

  // Sanitize user data based on access level
  const sanitizedUsers = users.map(user => sanitizeUserData(user, hasFullAccess));

  logger.info('Users endpoint accessed', {
    authenticated: !!req.user,
    userRole: req.user?.role || 'anonymous',
    ip: req.ip
  });

  res.json(sanitizedUsers);
});

// Example: Create user endpoint with validation
app.post('/users',
  strictLimiter,
  authenticateToken,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .matches(/^[a-zA-Z\s]+$/)
      .withMessage('Name must contain only letters and spaces'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address'),
  ],
  validate,
  (req, res) => {
    // Ensure only admins can create users
    if (req.user.role !== 'admin') {
      logger.warn(`Unauthorized user creation attempt by ${req.user.id}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    const { name, email } = req.body;

    // In production, save to database with proper error handling
    logger.info('User created', { name, email, createdBy: req.user.id });

    res.status(201).json({
      message: 'User created successfully',
      user: { name, email }
    });
  }
);

// Example: Login endpoint (mock implementation)
app.post('/login',
  strictLimiter,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }),
  ],
  validate,
  (req, res) => {
    const { email, password } = req.body;

    // In production, verify credentials against database
    // This is a mock implementation
    if (email === 'admin@example.com' && password === 'SecurePassword123!') {
      const token = jwt.sign(
        { id: 1, email, role: 'admin' },
        process.env.JWT_SECRET || 'dev-secret-key',
        { expiresIn: '1h' }
      );

      logger.info('Successful login', { email, ip: req.ip });

      res.json({
        token,
        expiresIn: 3600,
        user: { email, role: 'admin' }
      });
    } else {
      logger.warn('Failed login attempt', { email, ip: req.ip });
      // Use generic message to prevent user enumeration
      res.status(401).json({ error: 'Invalid credentials' });
    }
  }
);

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res, next) => {
  logger.warn('404 Not Found', { path: req.path, method: req.method, ip: req.ip });
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error
  logger.error('Application error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const isDevelopment = NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ===== SERVER STARTUP =====
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Detailed Security Recommendations

## Priority 1: Critical Vulnerabilities (Fix Immediately)

### 1. Implement Authentication
**Current Risk**: Anyone can access `/users` endpoint and retrieve email addresses.

**Solution**:
```bash
npm install jsonwebtoken bcrypt
```

Implement the authentication system shown in `app.secure.js`.

### 2. Add Input Validation
**Current Risk**: When POST/PUT endpoints are added, no validation exists.

**Solution**:
```bash
npm install express-validator
```

Always validate and sanitize user inputs using express-validator.

### 3. Add Security Headers
**Current Risk**: Missing headers leave application vulnerable to XSS, clickjacking, etc.

**Solution**:
```bash
npm install helmet
```

Apply Helmet middleware as shown in secure implementation.

## Priority 2: High Vulnerabilities (Fix Within 1 Week)

### 4. Implement Rate Limiting
**Current Risk**: No protection against brute force or DoS attacks.

**Solution**:
```bash
npm install express-rate-limit
```

Configure different rate limits for different endpoints.

### 5. Configure CORS Properly
**Current Risk**: No CORS policy allows any origin to make requests.

**Solution**:
```bash
npm install cors
```

Implement whitelist-based CORS as shown.

### 6. Add Comprehensive Logging
**Current Risk**: No audit trail for security events.

**Solution**:
```bash
npm install winston morgan
```

Implement structured logging with appropriate levels.

## Priority 3: Medium Vulnerabilities (Fix Within 1 Month)

### 7. Environment Configuration
**Current Risk**: Hardcoded values and no secret management.

**Solution**:
```bash
npm install dotenv
```

Create `.env` file (never commit to git) and use `.env.example` template.

### 8. Error Handling
**Current Risk**: Errors might leak sensitive information.

**Solution**:
Implement error handling middleware that:
- Logs detailed errors internally
- Returns generic errors to clients in production
- Provides details only in development

### 9. Data Sanitization
**Current Risk**: Exposing PII without proper authorization.

**Solution**:
- Implement data masking
- Use role-based access control
- Return only necessary fields

## Priority 4: Best Practices (Implement Before Production)

### 10. Password Security
If implementing user registration:

```javascript
const bcrypt = require('bcrypt');
const SALT_ROUNDS = 12;

// Hashing
const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);

// Verification
const isValid = await bcrypt.compare(password, hashedPassword);
```

### 11. JWT Best Practices

```javascript
// Short-lived access tokens
const accessToken = jwt.sign(
  { id: user.id, email: user.email },
  process.env.JWT_SECRET,
  { expiresIn: '15m' }
);

// Long-lived refresh tokens
const refreshToken = jwt.sign(
  { id: user.id },
  process.env.REFRESH_TOKEN_SECRET,
  { expiresIn: '7d' }
);
```

### 12. Database Security
When adding database:

```javascript
// Use parameterized queries
const query = 'SELECT * FROM users WHERE email = $1';
const result = await db.query(query, [email]);

// Never concatenate user input
// BAD: `SELECT * FROM users WHERE email = '${email}'`
```

### 13. API Versioning

```javascript
// Version your API
app.use('/api/v1/users', usersRouterV1);
app.use('/api/v2/users', usersRouterV2);
```

### 14. Health Checks Enhancement

```javascript
app.get('/health', async (req, res) => {
  const healthCheck = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    checks: {
      database: await checkDatabase(),
      redis: await checkRedis(),
      externalApi: await checkExternalApis()
    }
  };

  const status = Object.values(healthCheck.checks)
    .every(check => check === 'ok') ? 200 : 503;

  res.status(status).json(healthCheck);
});
```

## Security Testing

### 1. Unit Tests
```javascript
// tests/security.test.js
const request = require('supertest');
const app = require('../app');

describe('Security Tests', () => {
  test('should reject requests without authentication', async () => {
    const response = await request(app)
      .get('/users')
      .expect(401);
  });

  test('should reject invalid JWT tokens', async () => {
    const response = await request(app)
      .get('/users')
      .set('Authorization', 'Bearer invalid-token')
      .expect(403);
  });

  test('should enforce rate limiting', async () => {
    for (let i = 0; i < 101; i++) {
      await request(app).get('/health');
    }
    const response = await request(app)
      .get('/health')
      .expect(429);
  });
});
```

### 2. Security Scanning
```bash
# Install security tools
npm install -D snyk eslint-plugin-security

# Run security audit
npm audit
npx snyk test

# Run linter with security rules
npx eslint . --ext .js --plugin security
```

### 3. Penetration Testing Checklist
- [ ] Test SQL injection on all inputs
- [ ] Test XSS on all text inputs
- [ ] Test CSRF protection
- [ ] Test authentication bypass
- [ ] Test authorization bypass
- [ ] Test rate limiting
- [ ] Test file upload vulnerabilities (if applicable)
- [ ] Test session management
- [ ] Test password reset flow
- [ ] Test for sensitive data exposure

## Deployment Security

### Docker Security
```dockerfile
# Use specific versions, not 'latest'
FROM node:18.17.1-alpine

# Run as non-root user
RUN addgroup -g 1001 -S nodejs && \
    adduser -S nodejs -u 1001

USER nodejs

# Copy only necessary files
COPY --chown=nodejs:nodejs package*.json ./
COPY --chown=nodejs:nodejs . .

# Don't expose unnecessary ports
EXPOSE 3000

CMD ["node", "app.js"]
```

### Nginx Configuration
```nginx
# Rate limiting
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

server {
    listen 443 ssl http2;
    server_name api.example.com;

    # SSL Configuration
    ssl_certificate /path/to/cert.pem;
    ssl_certificate_key /path/to/key.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Security Headers
    add_header X-Frame-Options "DENY";
    add_header X-Content-Type-Options "nosniff";
    add_header X-XSS-Protection "1; mode=block";
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # Rate limiting
    limit_req zone=api_limit burst=20 nodelay;

    location / {
        proxy_pass http://localhost:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
    }
}
```

## Monitoring and Alerting

### CloudWatch/DataDog Example
```javascript
const metrics = require('./metrics');

// Track security events
app.use((req, res, next) => {
  res.on('finish', () => {
    metrics.increment('http.requests', {
      method: req.method,
      path: req.path,
      status: res.statusCode
    });

    if (res.statusCode === 401 || res.statusCode === 403) {
      metrics.increment('security.unauthorized', {
        path: req.path,
        ip: req.ip
      });
    }
