## 8. Authentication

### ❌ Original (Insecure)
```javascript
app.get('/users', (req, res) => {
  // No authentication check
  // Anyone can access this endpoint
  // Email addresses exposed to all

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### ✅ Secured
```javascript
// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', strictLimiter, authenticateToken, (req, res) => {
  // Only authenticated users can access
  // Data sanitized based on permissions

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const hasFullAccess = req.user && req.user.role === 'admin';
  const sanitizedUsers = users.map(user => 
    sanitizeUserData(user, hasFullAccess)
  );

  logger.info('Users endpoint accessed', {
    authenticated: true,
    userRole: req.user.role,
    ip: req.ip
  });

  res.json(sanitizedUsers);
});
```

**Security Benefit**: 
- Only authenticated users can access data
- JWT tokens with expiration
- Failed attempts logged
- Role-based access control

