    body('password').isLength({ min: 6 }),
  ],
  validate,
  (req, res) => {
    const { username, password } = req.body;

    // In production, verify against database with bcrypt
    if (username === 'admin' && password === 'admin123') {
      const token = jwt.sign(
        { username, role: 'admin' },
        process.env.JWT_SECRET,
        { expiresIn: '1h' }
      );
      logger.info(`Successful login: ${username}`);
      return res.json({ token, expiresIn: 3600 });
    }

    logger.warn(`Failed login attempt: ${username} from ${req.ip}`);
    res.status(401).json({ error: 'Invalid credentials' });
  }
);

app.get('/users', authenticateToken, (req, res) => {
  logger.info(`Users accessed by: ${req.user.username}`);

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/users',
  authenticateToken,
  [
    body('name').trim().isLength({ min: 2, max: 100 }),
    body('email').isEmail().normalizeEmail(),
  ],
  validate,
  (req, res) => {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    const { name, email } = req.body;
    logger.info(`User created: ${email} by ${req.user.username}`);

    res.status(201).json({ message: 'User created', user: { name, email } });
  }
);

// 404 handler
app.use((req, res) => {
  logger.warn(`404: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not found' });
});

// Error handler
app.use((err, req, res, next) => {
  logger.error('Error:', { error: err.message, stack: err.stack });
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal error'
  });
});

// Start server
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
  console.log(`Server running on port ${PORT}`);
});

