# Secrets Management Security Enhancement

## 🚨 Issue: VUL-011 - Insecure Secrets Management

**Severity**: HIGH  
**Current State**: Secrets loaded from `.env` files  
**Risk**: Plain-text secrets, no rotation, no audit trail

---

## ✅ Recommended Solutions

### Option 1: AWS Secrets Manager (Recommended for AWS)

```javascript
// secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secret');
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

**Usage in app.js:**

```javascript
const secretsManager = require('./secrets-manager');

// Initialize secrets on startup
let JWT_SECRET;
let DATABASE_URL;

async function initializeSecrets() {
  const secrets = await secretsManager.getSecret('myapp/production');
  JWT_SECRET = secrets.JWT_SECRET;
  DATABASE_URL = secrets.DATABASE_URL;
}

// Start server only after secrets are loaded
initializeSecrets()
  .then(() => {
    const server = app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  })
  .catch(err => {
    console.error('Failed to initialize secrets:', err);
    process.exit(1);
  });

// Use in authentication
const authenticateToken = (req, res, next) => {
  // ... existing code ...
  jwt.verify(token, JWT_SECRET, (err, user) => {
    // ... rest of code
  });
};
```

**AWS Secret Structure (JSON in AWS Secrets Manager):**
```json
{
  "JWT_SECRET": "generated-strong-secret-here",
  "DATABASE_URL": "postgresql://...",
  "SESSION_SECRET": "another-secret",
  "ALLOWED_ORIGINS": "https://app.example.com,https://api.example.com"
}
```

---

### Option 2: HashiCorp Vault (Recommended for Multi-Cloud)

```javascript
// vault-client.js
const vault = require('node-vault');

class VaultClient {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const result = await this.client.read(path);
      const secretValue = result.data.data || result.data;

      this.cache.set(path, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error reading secret from path ${path}:`, error);
      throw new Error('Failed to retrieve secret from Vault');
    }
  }

  async renewToken() {
    try {
      await this.client.tokenRenewSelf();
      console.log('Vault token renewed successfully');
    } catch (error) {
      console.error('Failed to renew Vault token:', error);
      throw error;
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new VaultClient();
```

**Usage:**

```javascript
const vaultClient = require('./vault-client');

async function initializeSecrets() {
  const secrets = await vaultClient.getSecret('secret/data/myapp');
  return secrets;
}

// Renew token periodically
setInterval(async () => {
  try {
    await vaultClient.renewToken();
  } catch (error) {
    console.error('Token renewal failed:', error);
  }
}, 3600000); // Every hour
```

---

### Option 3: Google Cloud Secret Manager

```javascript
// gcp-secrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    this.client = new SecretManagerServiceClient();
    this.cache = new Map();
    this.cacheTTL = 300000;
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const projectId = process.env.GCP_PROJECT_ID;
      const name = `projects/${projectId}/secrets/${secretName}/versions/latest`;

      const [version] = await this.client.accessSecretVersion({ name });
      const secretValue = version.payload.data.toString('utf8');

      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error accessing secret ${secretName}:`, error);
      throw new Error('Failed to access GCP secret');
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new GCPSecretsManager();
```

---

### Option 4: Azure Key Vault

```javascript
// azure-keyvault.js
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureKeyVaultClient {
  constructor() {
    const vaultUrl = process.env.AZURE_KEYVAULT_URL;
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
    this.cache = new Map();
    this.cacheTTL = 300000;
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const secret = await this.client.getSecret(secretName);

      this.cache.set(secretName, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to retrieve Azure Key Vault secret');
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new AzureKeyVaultClient();
```

---

## 🔐 Secret Rotation Strategy

### Automated Rotation Script

```javascript
// rotate-secrets.js
const crypto = require('crypto');
const secretsManager = require('./secrets-manager');

async function generateNewJWTSecret() {
  return crypto.randomBytes(32).toString('hex');
}

async function rotateSecrets() {
  console.log('Starting secret rotation...');

  try {
    // Generate new secrets
    const newJWTSecret = await generateNewJWTSecret();

    // Update in secrets manager
    await secretsManager.updateSecret('myapp/production', {
      JWT_SECRET: newJWTSecret,
      // Keep other secrets unchanged or rotate them too
    });

    console.log('Secrets rotated successfully');

    // Trigger application reload/restart
    // This depends on your deployment strategy

  } catch (error) {
    console.error('Secret rotation failed:', error);
    throw error;
  }
}

// Run rotation
rotateSecrets().catch(console.error);
```

### Rotation Schedule

```yaml
# GitHub Actions example: .github/workflows/rotate-secrets.yml
name: Rotate Secrets
on:
  schedule:
    - cron: '0 2 1 * *'  # 2 AM on the 1st of every month
  workflow_dispatch:  # Manual trigger

jobs:
  rotate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Setup Node.js
        uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: Install dependencies
        run: npm install
      - name: Rotate secrets
        run: node rotate-secrets.js
        env:
          AWS_REGION: ${{ secrets.AWS_REGION }}
          AWS_ACCESS_KEY_ID: ${{ secrets.AWS_ACCESS_KEY_ID }}
          AWS_SECRET_ACCESS_KEY: ${{ secrets.AWS_SECRET_ACCESS_KEY }}
```

---

## 📋 Migration Checklist

### Phase 1: Preparation
- [ ] Choose secrets management solution
- [ ] Set up infrastructure (AWS Secrets Manager, Vault, etc.)
- [ ] Create IAM roles/policies with least privilege
- [ ] Document secret naming conventions
- [ ] Plan migration timeline

### Phase 2: Secret Identification
- [ ] Audit all secrets currently in .env files
- [ ] Identify which secrets need rotation
- [ ] Create inventory of secret types:
  - [ ] JWT_SECRET
  - [ ] DATABASE_URL (contains password)
  - [ ] SESSION_SECRET
  - [ ] API keys
  - [ ] Encryption keys

### Phase 3: Migration
- [ ] Generate new secrets with proper entropy
- [ ] Store secrets in secrets manager
- [ ] Update application code to use secrets manager
- [ ] Test in development environment
- [ ] Test in staging environment
- [ ] Deploy to production with zero-downtime strategy

### Phase 4: Cleanup
- [ ] Remove .env files from production servers
- [ ] Update .gitignore to prevent .env commits
- [ ] Revoke/rotate old secrets
- [ ] Update documentation
- [ ] Train team on new process

### Phase 5: Ongoing
- [ ] Set up automated rotation (quarterly minimum)
- [ ] Enable audit logging for secret access
- [ ] Monitor for unauthorized access attempts
- [ ] Regular access review

---

## 🛡️ Security Best Practices

### 1. Least Privilege Access

```json
// AWS IAM Policy Example - minimum permissions
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "secretsmanager:GetSecretValue"
      ],
      "Resource": [
        "arn:aws:secretsmanager:region:account:secret:myapp/production-*"
      ]
    }
  ]
}
```

### 2. Audit Logging

```javascript
// Add audit logging to secrets access
async function getSecretWithAudit(secretName, requestContext) {
  logger.info('Secret access requested', {
    secret: secretName,
    requestedBy: requestContext.user,
    timestamp: new Date().toISOString(),
    ip: requestContext.ip
  });

  const secret = await secretsManager.getSecret(secretName);

  logger.info('Secret access granted', {
    secret: secretName,
    requestedBy: requestContext.user
  });

  return secret;
}
```

### 3. Encryption in Transit and at Rest

- ✅ Use TLS for all secrets manager API calls
- ✅ Ensure secrets are encrypted at rest in the secrets manager
- ✅ Use encrypted connections to databases

### 4. Secret Validation

```javascript
// Validate secret format before use
function validateJWTSecret(secret) {
  if (!secret || secret.length < 32) {
    throw new Error('JWT_SECRET must be at least 32 characters');
  }

  // Check it's not a default/example value
  const dangerousDefaults = [
    'your-secret-key',
    'change-me',
    'secret',
    'dev-secret-key'
  ];

  if (dangerousDefaults.some(bad => secret.includes(bad))) {
    throw new Error('JWT_SECRET appears to be a default value');
  }

  return true;
}
```

---

## 🚀 Quick Migration Example

```javascript
// app-with-secrets-manager.js
const express = require('express');
const secretsManager = require('./secrets-manager');
const jwt = require('jsonwebtoken');

const app = express();
let appSecrets;

// Initialize secrets on startup
async function initialize() {
  try {
    // Load secrets from AWS Secrets Manager
    appSecrets = await secretsManager.getSecret('myapp/production');

    // Validate secrets
    if (!appSecrets.JWT_SECRET || appSecrets.JWT_SECRET.length < 32) {
      throw new Error('Invalid JWT_SECRET');
    }

    console.log('Secrets loaded successfully');
    return true;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    process.exit(1);
  }
}

// Authentication middleware using secrets from secrets manager
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Use secret from secrets manager
  jwt.verify(token, appSecrets.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Routes
app.get('/users', authenticateToken, (req, res) => {
  res.json({ message: 'Protected data' });
});

// Start server only after secrets are initialized
initialize().then(() => {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
});

module.exports = app;
```

---

## 📊 Comparison: .env vs Secrets Manager

| Feature | .env Files | Secrets Manager |
|---------|-----------|----------------|
| Encryption at Rest | ❌ No | ✅ Yes |
| Audit Logging | ❌ No | ✅ Yes |
| Automatic Rotation | ❌ No | ✅ Yes |
| Access Control | ❌ File permissions only | ✅ IAM/RBAC |
| Centralized Management | ❌ No | ✅ Yes |
| Version Control Safe | ⚠️ Risk of commit | ✅ Yes |
| Cross-Environment | ❌ Manual | ✅ Automatic |
| Compliance Ready | ❌ No | ✅ Yes |
| Cost | ✅ Free | 💰 ~$0.40/secret/month |

---

## ⚠️ Common Pitfalls to Avoid

1. **Don't log secrets** - Even in error messages
2. **Don't cache indefinitely** - Implement TTL
3. **Don't use defaults in production** - Validate on startup
4. **Don't skip error handling** - App should fail safely
5. **Don't forget to rotate** - Set up automated rotation
6. **Don't over-privilege** - Use least privilege IAM policies

---

## 🎯 Summary

**Current Risk**: HIGH - Plain-text secrets in .env files  
**Recommended Action**: Migrate to AWS Secrets Manager, Vault, or equivalent  
**Effort**: 4-8 hours initial setup + testing  
**Ongoing**: Automated rotation every 90 days  
**ROI**: Significantly reduced breach risk, compliance ready

**Next Steps**:
1. Choose a secrets manager based on your infrastructure
2. Follow the migration checklist
3. Implement automated rotation
4. Set up monitoring and alerts
5. Train team on new workflow

This is a critical security enhancement that should be prioritized for production deployments.

