// Security Middleware Collection
// Reusable security middleware for Express.js applications

const jwt = require('jsonwebtoken');
const validator = require('validator');
const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * JWT Authentication Middleware
 * Verifies JWT token from Authorization header
 */
const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      logger.warn('Authentication failed: No token provided', {
        ip: req.ip,
        path: req.path,
        method: req.method,
      });
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'Access token is required' 
      });
    }

    const secret = process.env.JWT_SECRET;
    if (!secret) {
      logger.error('JWT_SECRET not configured');
      return res.status(500).json({ 
        error: 'Server Error',
        message: 'Authentication is not properly configured' 
      });
    }

    jwt.verify(token, secret, (err, decoded) => {
      if (err) {
        logger.warn('Authentication failed: Invalid token', {
          ip: req.ip,
          path: req.path,
          error: err.message,
        });
        return res.status(403).json({ 
          error: 'Forbidden',
          message: 'Invalid or expired token' 
        });
      }

      req.user = decoded;
      logger.info('User authenticated successfully', { userId: decoded.id });
      next();
    });
  } catch (error) {
    logger.error('Authentication error', { error: error.message });
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Authentication failed' 
    });
  }
};

/**
 * Optional Authentication Middleware
 * Authenticates if token present, but doesn't fail if absent
 */
const authenticateOptional = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return next();
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return next();
  }

  jwt.verify(token, secret, (err, decoded) => {
    if (!err) {
      req.user = decoded;
    }
    next();
  });
};

// ============================================
// AUTHORIZATION MIDDLEWARE
// ============================================

/**
 * Role-based Authorization Middleware
 * @param {Array<string>} allowedRoles - Array of role names
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      logger.warn('Authorization failed: User not authenticated');
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'Authentication required' 
      });
    }

    const userRole = req.user.role;

    if (!allowedRoles.includes(userRole)) {
      logger.warn('Authorization failed: Insufficient permissions', {
        userId: req.user.id,
        userRole,
        requiredRoles: allowedRoles,
        path: req.path,
      });
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'You do not have permission to access this resource' 
      });
    }

    logger.info('User authorized', { 
      userId: req.user.id, 
      role: userRole 
    });
    next();
  };
};

/**
 * Resource Owner Authorization
 * Checks if user owns the resource they're trying to access
 */
const authorizeOwner = (resourceIdParam = 'id') => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'Authentication required' 
      });
    }

    const resourceId = parseInt(req.params[resourceIdParam], 10);
    const userId = req.user.id;

    // Allow access if user is owner or admin
    if (userId !== resourceId && req.user.role !== 'admin') {
      logger.warn('Authorization failed: User tried to access another user\'s resource', {
        userId,
        attemptedResourceId: resourceId,
      });
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'You can only access your own resources' 
      });
    }

    next();
  };
};

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Validate Integer ID Parameter
 */
const validateId = (paramName = 'id') => {
  return (req, res, next) => {
    const value = req.params[paramName];

    if (!value) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: `${paramName} is required` 
      });
    }

    if (!validator.isInt(value, { min: 1 })) {
      logger.warn('Validation failed: Invalid ID format', { 
        param: paramName, 
        value 
      });
      return res.status(400).json({ 
        error: 'Bad Request',
        message: `Invalid ${paramName} format` 
      });
    }

    req.params[`sanitized_${paramName}`] = parseInt(value, 10);
    next();
  };
};

/**
 * Validate Email in Request Body
 */
const validateEmail = (fieldName = 'email') => {
  return (req, res, next) => {
    const email = req.body[fieldName];

    if (!email) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: `${fieldName} is required` 
      });
    }

    if (!validator.isEmail(email)) {
      logger.warn('Validation failed: Invalid email', { email });
      return res.status(400).json({ 
        error: 'Bad Request',
        message: 'Invalid email format' 
      });
    }

    // Normalize email
    req.body[fieldName] = validator.normalizeEmail(email);
    next();
  };
};

/**
 * Validate Pagination Parameters
 */
const validatePagination = (req, res, next) => {
  const { page = '1', limit = '10' } = req.query;

  if (!validator.isInt(page, { min: 1 })) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid page parameter' 
    });
  }

  if (!validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid limit parameter (1-100)' 
    });
  }

  req.pagination = {
    page: parseInt(page, 10),
    limit: parseInt(limit, 10),
    offset: (parseInt(page, 10) - 1) * parseInt(limit, 10),
  };

  next();
};

/**
 * Sanitize String Input
 * Escapes HTML and trims whitespace
 */
const sanitizeString = (fieldNames) => {
  return (req, res, next) => {
    const fields = Array.isArray(fieldNames) ? fieldNames : [fieldNames];

    fields.forEach(field => {
      if (req.body[field] && typeof req.body[field] === 'string') {
        req.body[field] = validator.escape(validator.trim(req.body[field]));
      }
    });

    next();
  };
};

/**
 * Validate UUID
 */
const validateUUID = (paramName = 'id') => {
  return (req, res, next) => {
    const value = req.params[paramName];

    if (!value || !validator.isUUID(value)) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: `Invalid ${paramName} format` 
      });
    }

    next();
  };
};

// ============================================
// REQUEST VALIDATION SCHEMAS
// ============================================

/**
 * Validate Request Body Against Schema
 * @param {Object} schema - Validation schema
 */
const validateBody = (schema) => {
  return (req, res, next) => {
    const errors = [];

    // Check required fields
    if (schema.required) {
      schema.required.forEach(field => {
        if (!req.body[field]) {
          errors.push(`${field} is required`);
        }
      });
    }

    // Validate field types and constraints
    Object.keys(schema.fields || {}).forEach(field => {
      const value = req.body[field];
      const rules = schema.fields[field];

      if (value !== undefined && value !== null) {
        // Type validation
        if (rules.type === 'email' && !validator.isEmail(value)) {
          errors.push(`${field} must be a valid email`);
        }
        if (rules.type === 'url' && !validator.isURL(value)) {
          errors.push(`${field} must be a valid URL`);
        }
        if (rules.type === 'number' && !validator.isNumeric(String(value))) {
          errors.push(`${field} must be a number`);
        }

        // Length validation
        if (rules.minLength && value.length < rules.minLength) {
          errors.push(`${field} must be at least ${rules.minLength} characters`);
        }
        if (rules.maxLength && value.length > rules.maxLength) {
          errors.push(`${field} must be at most ${rules.maxLength} characters`);
        }

        // Pattern validation
        if (rules.pattern && !new RegExp(rules.pattern).test(value)) {
          errors.push(`${field} format is invalid`);
        }
      }
    });

    if (errors.length > 0) {
      logger.warn('Request validation failed', { errors, body: req.body });
      return res.status(400).json({ 
        error: 'Validation Error',
        message: 'Request validation failed',
        errors 
      });
    }

    next();
  };
};

// ============================================
// SECURITY HEADERS MIDDLEWARE
// ============================================

/**
 * Add Custom Security Headers
 */
const securityHeaders = (req, res, next) => {
  // Remove Express fingerprinting
  res.removeHeader('X-Powered-By');

  // Additional security headers (complement Helmet)
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
};

// ============================================
// ASYNC ERROR HANDLER WRAPPER
// ============================================

/**
 * Wraps async route handlers to catch errors
 * @param {Function} fn - Async route handler
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ============================================
// EXPORTS
// ============================================

module.exports = {
  // Authentication
  authenticateToken,
  authenticateOptional,

  // Authorization
  authorize,
  authorizeOwner,

  // Validation
  validateId,
  validateEmail,
  validatePagination,
  validateUUID,
  validateBody,
  sanitizeString,

  // Security
  securityHeaders,

  // Utilities
  asyncHandler,
  logger,
};

// Example: Secure User Management Routes
// Demonstrates proper security implementation

const express = require('express');
const router = express.Router();
const {
