/**
 * POST /api/users
 * Create new user (Public registration)
 */
router.post('/',
  validateBody(createUserSchema),
  validateEmail('email'),
  asyncHandler(async (req, res) => {
    const { email, password, name } = req.body;

    // Check if user exists
    const existingUser = await db.findByEmail(email);
    if (existingUser) {
      logger.warn('Registration attempt with existing email', { email });
      return res.status(409).json({
        error: 'Conflict',
        message: 'User with this email already exists'
      });
    }

    // Hash password (never store plain text!)
    const bcrypt = require('bcrypt');
    const saltRounds = parseInt(process.env.BCRYPT_ROUNDS) || 12;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    // Create user with parameterized query
    const query = `
      INSERT INTO users (email, password_hash, name, created_at) 
      VALUES ($1, $2, $3, NOW()) 
      RETURNING id, email, name, created_at
    `;

    // Simulate user creation
    const newUser = {
      id: db.users.length + 1,
      email,
      name,
      created_at: new Date().toISOString()
    };

    logger.info('New user registered', { 
      userId: newUser.id, 
      email: newUser.email 
    });

    // Don't return password hash!
    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  })
);

/**
 * PUT /api/users/:id
 * Update user (Owner or Admin only)
 */
router.put('/:id',
  authenticateToken,
  validateId('id'),
  authorizeOwner('id'),
  validateBody(updateUserSchema),
  asyncHandler(async (req, res) => {
    const userId = req.params.sanitized_id;
    const updates = req.body;

    // Build dynamic update query safely
    const allowedFields = ['name', 'email', 'bio'];
    const updateFields = Object.keys(updates).filter(key => 
      allowedFields.includes(key)
    );

    if (updateFields.length === 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'No valid fields to update'
      });
    }

    // Build parameterized query
    const setClause = updateFields.map((field, idx) => 
      `${field} = $${idx + 1}`
    ).join(', ');

    const values = updateFields.map(field => updates[field]);
    values.push(userId);

    const query = `
      UPDATE users 
      SET ${setClause}, updated_at = NOW() 
      WHERE id = $${values.length}
      RETURNING id, name, email, bio, updated_at
    `;

    // Execute update
    const updatedUser = await db.findById(userId);

    if (!updatedUser) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found'
      });
    }

    logger.info('User updated', { 
      userId, 
      updatedBy: req.user.id,
      fields: updateFields 
    });

    res.json({
      success: true,
      message: 'User updated successfully',
      data: updatedUser
    });
  })
);

/**
 * DELETE /api/users/:id
 * Delete user (Owner or Admin only)
 */
router.delete('/:id',
  authenticateToken,
  validateId('id'),
  authorizeOwner('id'),
  asyncHandler(async (req, res) => {
    const userId = req.params.sanitized_id;

    // Check if user exists
    const user = await db.findById(userId);
    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found'
      });
    }

    // Soft delete (recommended) or hard delete
    const query = 'UPDATE users SET deleted_at = NOW() WHERE id = $1';
    // Or for hard delete: 'DELETE FROM users WHERE id = $1'

    await db.query(query, [userId]);

    logger.warn('User deleted', { 
      userId, 
      deletedBy: req.user.id 
    });

    res.json({
      success: true,
      message: 'User deleted successfully'
    });
  })
);

/**
 * POST /api/users/search
 * Search users (Authenticated users)
 * Body: { query: string }
 */
router.post('/search',
  authenticateToken,
  validatePagination,
  asyncHandler(async (req, res) => {
    const { query: searchQuery } = req.body;
    const { limit, offset } = req.pagination;

    if (!searchQuery || typeof searchQuery !== 'string') {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Search query is required'
      });
    }

    // Sanitize search input (prevent SQL injection)
    const sanitizedQuery = searchQuery.trim();

    if (sanitizedQuery.length < 2) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Search query must be at least 2 characters'
      });
    }

    // Use parameterized query with LIKE (or full-text search)
    const sql = `
      SELECT id, name, email 
      FROM users 
      WHERE name ILIKE $1 OR email ILIKE $1
      LIMIT $2 OFFSET $3
    `;

    const searchPattern = `%${sanitizedQuery}%`;
    const results = await db.query(sql, [searchPattern, limit, offset]);

    logger.info('User search performed', { 
      userId: req.user.id, 
      query: sanitizedQuery 
    });

    res.json({
      success: true,
      data: results,
      query: sanitizedQuery
    });
  })
);

// ============================================
// ERROR HANDLING FOR THIS ROUTER
// ============================================

router.use((err, req, res, next) => {
  logger.error('User route error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    userId: req.user?.id
  });

  res.status(err.statusCode || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  });
});

module.exports = router;

