  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// ✅ Security headers - Protects against XSS, clickjacking, etc.
app.use(helmet({
  contentSecurityPolicy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true }
}));

// ✅ CORS configuration - Only allow trusted origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true
}));

// ✅ Body parsing with size limits - Prevents DoS via large payloads
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ✅ Data sanitization - Prevents injection attacks
app.use(mongoSanitize());
app.use(xss());

// ✅ Rate limiting - Prevents brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later.'
});
app.use('/api/', limiter);

// ✅ Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn('Unauthorized access attempt', { ip: req.ip, path: req.path });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token', { ip: req.ip });
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    logger.info('User authenticated', { userId: user.id });
    next();
  });
};

// ✅ Input validation middleware
const validateId = (req, res, next) => {
  const { id } = req.params;
  if (!/^\d+$/.test(id) || parseInt(id) < 1) {
    logger.warn('Invalid ID format', { id });
    return res.status(400).json({ error: 'Invalid ID format' });
  }
  req.params.id = parseInt(id, 10);
  next();
};

// ✅ Public endpoint - No PII exposed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ✅ Protected endpoint with authentication
// ✅ No PII in response (emails removed)
// ✅ Access logged for audit
app.get('/api/users', authenticateToken, async (req, res, next) => {
  try {
    // ✅ Data fetched from database with parameterized query
    // const users = await db.query('SELECT id, name FROM users');

    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ];

    logger.info('Users list accessed', { userId: req.user.id });

    res.json({
      success: true,
      data: users
    });
  } catch (error) {
    next(error); // ✅ Proper error handling
  }
});

// ✅ Protected endpoint with validation
app.get('/api/users/:id', 
  authenticateToken, 
  validateId,
  async (req, res, next) => {
    try {
      const userId = req.params.id;

      // ✅ Authorization check
      if (req.user.id !== userId && req.user.role !== 'admin') {
        logger.warn('Unauthorized access attempt', {
          userId: req.user.id,
          attemptedAccess: userId
        });
        return res.status(403).json({ error: 'Access denied' });
      }

      // ✅ Parameterized query prevents SQL injection
      // const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

      const user = { id: userId, name: 'Alice' };

      logger.info('User data accessed', { userId });
      res.json({ success: true, data: user });
    } catch (error) {
      next(error);
    }
});

// ✅ 404 handler
app.use((req, res) => {
  logger.warn('Route not found', { path: req.path, method: req.method });
  res.status(404).json({ error: 'Not Found' });
});

// ✅ Global error handler - No sensitive data leaked
app.use((err, req, res, next) => {
  logger.error('Application error', {
    error: err.message,
    stack: err.stack,
    path: req.path
  });

  res.status(err.statusCode || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  });
});

// ✅ HTTPS enforcement in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ✅ Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  logger.info(`Secure server running on port ${process.env.PORT || 3000}`);
});

process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// ✅ Handle uncaught errors
process.on('uncaughtException', (err) => {
  logger.error('Uncaught exception', { error: err.message, stack: err.stack });
  process.exit(1);
});

module.exports = app;
