### 2. Validate Secrets on Startup
```javascript
function validateSecrets() {
  const errors = [];

  if (!process.env.JWT_SECRET) {
    errors.push('JWT_SECRET is required');
  } else if (process.env.JWT_SECRET.length < 32) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  if (!process.env.DATABASE_URL) {
    errors.push('DATABASE_URL is required');
  } else if (!process.env.DATABASE_URL.startsWith('postgresql://')) {
    errors.push('DATABASE_URL must be a valid PostgreSQL connection string');
  }

  if (errors.length > 0) {
    console.error('Configuration errors:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }
}
```

### 3. Use Type-Safe Configuration
```javascript
class Config {
  constructor() {
    this.jwtSecret = this.requireSecret('JWT_SECRET', 32);
    this.databaseUrl = this.requireSecret('DATABASE_URL');
  }

  requireSecret(name, minLength = 1) {
    const value = process.env[name];

    if (!value) {
      throw new Error(`${name} environment variable is required`);
    }

    if (value.length < minLength) {
      throw new Error(`${name} must be at least ${minLength} characters`);
    }

    return value;
  }

  // Never allow serialization of secrets
  toJSON() {
    return {
      hasJwtSecret: !!this.jwtSecret,
      hasDatabaseUrl: !!this.databaseUrl,
    };
  }
}

const config = new Config();
