// scripts/rotate-secrets.js
const { SecretsManagerClient, UpdateSecretCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

async function rotateSecret(secretName, secretValue) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  try {
    const command = new UpdateSecretCommand({
      SecretId: secretName,
      SecretString: JSON.stringify(secretValue),
    });

    await client.send(command);
    console.log(`✅ Secret ${secretName} rotated successfully`);
  } catch (error) {
    console.error(`❌ Failed to rotate secret ${secretName}:`, error);
    throw error;
  }
}

// Example: Rotate JWT secret
