// config/secrets.js

/**
 * Secure secrets management supporting multiple backends:
 * - AWS Secrets Manager
 * - HashiCorp Vault
 * - Azure Key Vault
 * - Google Cloud Secret Manager
 * - Environment variables (fallback for development)
 */

const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
    this.provider = process.env.SECRETS_PROVIDER || 'env';
    this.initializeProvider();
  }

  initializeProvider() {
    switch (this.provider) {
      case 'aws':
        this.client = new AWS.SecretsManager({
          region: process.env.AWS_REGION || 'us-east-1'
        });
        break;
      case 'vault':
        // Initialize Vault client
        this.initializeVault();
        break;
      case 'azure':
        // Initialize Azure Key Vault
        this.initializeAzure();
        break;
      case 'gcp':
        // Initialize GCP Secret Manager
        this.initializeGCP();
        break;
      default:
        // Fallback to environment variables (dev only)
        if (process.env.NODE_ENV === 'production') {
          throw new Error('Secrets manager must be configured for production');
        }
        console.warn('⚠️  Using environment variables for secrets (NOT FOR PRODUCTION)');
    }
  }

  /**
   * Get secret from configured provider with caching
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && !forceRefresh && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    let secretValue;

    try {
      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAWSSecret(secretName);
          break;
        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;
        case 'azure':
          secretValue = await this.getAzureSecret(secretName);
          break;
        case 'gcp':
          secretValue = await this.getGCPSecret(secretName);
          break;
        default:
          secretValue = process.env[secretName];
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`, error.message);
      throw new Error('Secret retrieval failed');
    }
  }

  /**
   * AWS Secrets Manager implementation
   */
  async getAWSSecret(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        return data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        return buff.toString('ascii');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * HashiCorp Vault implementation
   */
  async initializeVault() {
    const vault = require('node-vault');

    this.vaultClient = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });

    // Use AppRole authentication in production
    if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
      const result = await this.vaultClient.approleLogin({
        role_id: process.env.VAULT_ROLE_ID,
        secret_id: process.env.VAULT_SECRET_ID
      });
      this.vaultClient.token = result.auth.client_token;
    }
  }

  async getVaultSecret(secretPath) {
    try {
      const result = await this.vaultClient.read(secretPath);
      return result.data.data || result.data;
    } catch (error) {
      throw new Error(`Vault secret retrieval failed: ${error.message}`);
    }
  }

  /**
   * Azure Key Vault implementation
   */
  async initializeAzure() {
    const { DefaultAzureCredential } = require('@azure/identity');
    const { SecretClient } = require('@azure/keyvault-secrets');

    const credential = new DefaultAzureCredential();
    const vaultUrl = process.env.AZURE_VAULT_URL;

    if (!vaultUrl) {
      throw new Error('AZURE_VAULT_URL not configured');
    }

    this.azureClient = new SecretClient(vaultUrl, credential);
  }

  async getAzureSecret(secretName) {
    try {
      const secret = await this.azureClient.getSecret(secretName);
      return secret.value;
    } catch (error) {
      throw new Error(`Azure Key Vault retrieval failed: ${error.message}`);
    }
  }

  /**
   * Google Cloud Secret Manager implementation
   */
  async initializeGCP() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    this.gcpClient = new SecretManagerServiceClient();
    this.gcpProjectId = process.env.GCP_PROJECT_ID;
  }

  async getGCPSecret(secretName) {
    try {
      const name = `projects/${this.gcpProjectId}/secrets/${secretName}/versions/latest`;
      const [version] = await this.gcpClient.accessSecretVersion({ name });
      return version.payload.data.toString();
    } catch (error) {
      throw new Error(`GCP Secret Manager retrieval failed: ${error.message}`);
    }
  }

  /**
   * Batch get multiple secrets
   */
  async getSecrets(secretNames) {
    const secrets = {};
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }

  /**
   * Clear cache (useful for rotation)
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }

  /**
   * Validate required secrets are present
   */
  async validateSecrets(requiredSecrets) {
    const missing = [];

    for (const secret of requiredSecrets) {
      try {
        const value = await this.getSecret(secret);
        if (!value) {
          missing.push(secret);
        }
      } catch (error) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }
}

