// scripts/rotate-secrets.js

const { getSecretsManager } = require('../config/secrets');
const crypto = require('crypto');

async function rotateSecret(secretName, generator) {
  const secretsManager = getSecretsManager();

  console.log(`🔄 Rotating secret: ${secretName}`);

  try {
    // Generate new secret value
    const newValue = generator ? generator() : crypto.randomBytes(32).toString('base64');

    // Update in secrets manager
    if (secretsManager.provider === 'aws') {
      await secretsManager.client.updateSecret({
        SecretId: secretName,
        SecretString: newValue
      }).promise();
    }

    // Clear cache
    secretsManager.clearCache(secretName);

    console.log(`✅ Secret rotated successfully: ${secretName}`);

    // Grace period before old secret becomes invalid
    await new Promise(resolve => setTimeout(resolve, 300000)); // 5 minutes

  } catch (error) {
    console.error(`❌ Failed to rotate secret: ${secretName}`, error);
    throw error;
  }
}

// Rotate JWT secret
async function rotateJWTSecret() {
  await rotateSecret('JWT_SECRET', () => {
    return crypto.randomBytes(64).toString('base64');
  });
}

// Run rotation
if (require.main === module) {
  rotateJWTSecret()
    .then(() => console.log('✅ Rotation complete'))
    .catch(err => {
      console.error('❌ Rotation failed:', err);
      process.exit(1);
    });
}

module.exports = { rotateSecret, rotateJWTSecret };
