const AWS = require('aws-sdk');
const NodeCache = require('node-cache');

// Cache secrets for 5 minutes to reduce API calls
const secretsCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.secretsLoaded = false;
    this.secrets = {};
  }

  /**
   * Load a secret from AWS Secrets Manager
   * @param {string} secretName - Name of the secret in AWS
   * @param {boolean} forceRefresh - Force refresh from AWS (skip cache)
   * @returns {Promise<object|string>} - The secret value
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && secretsCache.has(secretName)) {
      console.log(`[SECRETS] Retrieved ${secretName} from cache`);
      return secretsCache.get(secretName);
    }

    try {
      console.log(`[SECRETS] Fetching ${secretName} from AWS Secrets Manager`);

      const data = await this.client.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = data.SecretString;
        // Try to parse as JSON
        try {
          secret = JSON.parse(secret);
        } catch (e) {
          // Keep as string if not JSON
        }
      } else {
        // Binary secret
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      secretsCache.set(secretName, secret);

      // Log access (without the actual secret value)
      this.logSecretAccess(secretName, 'retrieved');

      return secret;
    } catch (error) {
      console.error(`[SECRETS] Error retrieving secret ${secretName}:`, error.code);

      // Log the failure
      this.logSecretAccess(secretName, 'failed', error.code);

      // Don't expose error details
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Load all application secrets at startup
   */
  async loadAllSecrets() {
    if (this.secretsLoaded) {
      return this.secrets;
    }

    try {
      console.log('[SECRETS] Loading application secrets...');

      // Define all secrets your app needs
      const secretNames = {
        database: 'prod/app/database',
        jwt: 'prod/app/jwt',
        stripe: 'prod/app/stripe',
        aws: 'prod/app/aws-credentials',
        anthropic: 'prod/app/anthropic',
        smtp: 'prod/app/smtp'
      };

      // Load all secrets in parallel
      const secretPromises = Object.entries(secretNames).map(
        async ([key, secretName]) => {
          try {
            const value = await this.getSecret(secretName);
            return { key, value };
          } catch (error) {
            console.error(`[SECRETS] Failed to load ${key}:`, error.message);
            // Fail fast - don't start app with missing secrets
            throw new Error(`Critical secret missing: ${key}`);
          }
        }
      );

      const results = await Promise.all(secretPromises);

      // Store secrets in memory
      results.forEach(({ key, value }) => {
        this.secrets[key] = value;
      });

      this.secretsLoaded = true;
      console.log('[SECRETS] All secrets loaded successfully');

      return this.secrets;
    } catch (error) {
      console.error('[SECRETS] Failed to load secrets:', error.message);
      // Exit if secrets can't be loaded
      process.exit(1);
    }
  }

  /**
   * Get a specific secret value
   */
  get(secretKey) {
    if (!this.secretsLoaded) {
      throw new Error('Secrets not loaded. Call loadAllSecrets() first.');
    }

    if (!this.secrets[secretKey]) {
      throw new Error(`Secret not found: ${secretKey}`);
    }

    return this.secrets[secretKey];
  }

  /**
   * Rotate a secret (useful for scheduled rotation)
   */
  async rotateSecret(secretName) {
    console.log(`[SECRETS] Rotating secret: ${secretName}`);

    try {
      await this.client.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
      }).promise();

      // Clear from cache to force reload
      secretsCache.del(secretName);

      this.logSecretAccess(secretName, 'rotated');
      console.log(`[SECRETS] Successfully rotated: ${secretName}`);
    } catch (error) {
      console.error(`[SECRETS] Failed to rotate ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Log secret access for audit trail
   */
  logSecretAccess(secretName, action, error = null) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      secretName,
      action, // 'retrieved', 'failed', 'rotated'
      error,
      service: 'secrets-manager',
      environment: process.env.NODE_ENV || 'development'
    };

    // In production, send to CloudWatch Logs or your SIEM
    if (process.env.NODE_ENV === 'production') {
      // Send to CloudWatch, Splunk, DataDog, etc.
      console.log('[AUDIT]', JSON.stringify(logEntry));
    } else {
      console.log('[SECRETS-AUDIT]', logEntry);
    }
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    secretsCache.flushAll();
    console.log('[SECRETS] Cache cleared');
  }

  /**
   * Health check - verify secrets manager is accessible
   */
  async healthCheck() {
    try {
      await this.client.listSecrets({ MaxResults: 1 }).promise();
      return { healthy: true, service: 'AWS Secrets Manager' };
    } catch (error) {
      return { 
        healthy: false, 
        service: 'AWS Secrets Manager',
        error: error.code 
      };
    }
  }
}

