// Secure Express app with proper secrets management

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

// Import secrets manager (choose one based on your infrastructure)
// Option 1: AWS Secrets Manager
const secretsManager = require('./config/secrets-manager');

// Option 2: HashiCorp Vault
// const secretsManager = require('./config/secrets-vault');

const app = express();

// ============================================
// INITIALIZE SECRETS BEFORE STARTING SERVER
// ============================================
async function initializeApp() {
  try {
    console.log('🔐 Initializing secrets...');

    // Load all secrets at startup
    await secretsManager.loadAllSecrets();

    // Verify secrets manager health
    const health = await secretsManager.healthCheck();
    if (!health.healthy) {
      console.error('❌ Secrets manager unhealthy:', health);
      process.exit(1);
    }

    console.log('✅ Secrets loaded successfully');

    // Now configure app with secrets
    configureApp();
    startServer();

  } catch (error) {
    console.error('❌ Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// ============================================
// CONFIGURE APPLICATION
// ============================================
function configureApp() {
  // Security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
      },
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    }
  }));

  // CORS - using secrets for allowed origins
  const corsOptions = {
    origin: function (origin, callback) {
      // Get allowed origins from secrets manager
      const allowedOrigins = secretsManager.get('app')?.allowedOrigins || [];

      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true
  };
  app.use(cors(corsOptions));

  // Body parsing
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ extended: true, limit: '10kb' }));

  // Logging
  app.use(morgan('combined'));

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: 'Too many requests'
  });
  app.use('/api/', limiter);
}

