      secretsManager.clearCache();

      // Reload secrets
      await secretsManager.loadAllSecrets();

      console.log(`✅ Secret rotated: ${secretName}`);
      res.json({ success: true, message: 'Secret rotated successfully' });
    } catch (error) {
