// secrets-manager.js - Secure secrets management with multiple provider support

const AWS = require('aws-sdk');
const { SecretManagerServiceClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretManagerServiceClient: GCPSecretManager } = require('@google-cloud/secret-manager');

class SecretsManager {
  constructor() {
    this.provider = process.env.SECRETS_PROVIDER || 'env'; // 'aws', 'gcp', 'azure', 'vault', 'env'
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes default
    this.initialized = false;
  }

  /**
   * Initialize the secrets manager based on provider
   */
  async initialize() {
    if (this.initialized) return;

    switch (this.provider) {
      case 'aws':
        this.client = new SecretManagerServiceClient({
          region: process.env.AWS_REGION || 'us-east-1'
        });
        break;

      case 'gcp':
        this.client = new GCPSecretManager();
        this.projectId = process.env.GCP_PROJECT_ID;
        break;

      case 'azure':
        const { SecretClient } = require('@azure/keyvault-secrets');
        const { DefaultAzureCredential } = require('@azure/identity');
        const vaultUrl = process.env.AZURE_KEY_VAULT_URL;
        this.client = new SecretClient(vaultUrl, new DefaultAzureCredential());
        break;

      case 'vault':
        const vault = require('node-vault');
        this.client = vault({
          apiVersion: 'v1',
          endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
          token: process.env.VAULT_TOKEN
        });
        break;

      case 'env':
        console.warn('⚠️  WARNING: Using environment variables for secrets. Not recommended for production!');
        break;

      default:
        throw new Error(`Unsupported secrets provider: ${this.provider}`);
    }

    this.initialized = true;
    console.log(`✓ Secrets Manager initialized with provider: ${this.provider}`);
  }

  /**
   * Get secret value with caching
   */
  async getSecret(secretName, options = {}) {
    await this.initialize();

    const { bypassCache = false, version = 'latest' } = options;

    // Check cache first
    const cacheKey = `${secretName}:${version}`;
    if (!bypassCache && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
      this.cache.delete(cacheKey);
    }

    let secretValue;

    try {
      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAWSSecret(secretName, version);
          break;

        case 'gcp':
          secretValue = await this.getGCPSecret(secretName, version);
          break;

        case 'azure':
          secretValue = await this.getAzureSecret(secretName, version);
          break;

        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;

        case 'env':
          secretValue = process.env[secretName];
          if (!secretValue) {
            throw new Error(`Environment variable ${secretName} not found`);
          }
          break;

        default:
          throw new Error(`Provider ${this.provider} not implemented`);
      }

      // Cache the secret
      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  /**
   * AWS Secrets Manager implementation
   */
  async getAWSSecret(secretName, version) {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: version === 'latest' ? 'AWSCURRENT' : version
    });

    const response = await this.client.send(command);

    if (response.SecretString) {
      // Handle JSON secrets
      try {
        return JSON.parse(response.SecretString);
      } catch {
        return response.SecretString;
      }
    } else if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    throw new Error('No secret value found');
  }

  /**
   * GCP Secret Manager implementation
   */
  async getGCPSecret(secretName, version) {
    const name = version === 'latest'
      ? `projects/${this.projectId}/secrets/${secretName}/versions/latest`
      : `projects/${this.projectId}/secrets/${secretName}/versions/${version}`;

    const [accessResponse] = await this.client.accessSecretVersion({ name });
    const secretValue = accessResponse.payload.data.toString('utf8');

    try {
      return JSON.parse(secretValue);
    } catch {
      return secretValue;
    }
  }

  /**
   * Azure Key Vault implementation
   */
  async getAzureSecret(secretName, version) {
    const secret = version === 'latest'
      ? await this.client.getSecret(secretName)
      : await this.client.getSecret(secretName, { version });

    try {
      return JSON.parse(secret.value);
    } catch {
      return secret.value;
    }
  }

  /**
   * HashiCorp Vault implementation
   */
  async getVaultSecret(secretName) {
    const path = process.env.VAULT_SECRET_PATH || 'secret/data';
    const result = await this.client.read(`${path}/${secretName}`);
    return result.data.data;
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => 
      this.getSecret(name).catch(err => ({ error: err.message }))
    );

    const results = await Promise.all(promises);

    return secretNames.reduce((acc, name, index) => {
      acc[name] = results[index];
      return acc;
    }, {});
  }

  /**
   * Rotate secret (trigger rotation)
   */
  async rotateSecret(secretName) {
    await this.initialize();

    switch (this.provider) {
      case 'aws':
        const { RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');
        await this.client.send(new RotateSecretCommand({ SecretId: secretName }));
        break;

      default:
        throw new Error(`Secret rotation not implemented for ${this.provider}`);
    }

    // Clear from cache
    this.cache.delete(`${secretName}:latest`);
    console.log(`✓ Secret ${secretName} rotation triggered`);
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.cache.clear();
    console.log('✓ Secrets cache cleared');
  }

  /**
   * Validate required secrets exist
   */
  async validateSecrets(requiredSecrets) {
    const errors = [];

    for (const secretName of requiredSecrets) {
      try {
        await this.getSecret(secretName);
      } catch (error) {
        errors.push(`Missing required secret: ${secretName}`);
      }
    }

    if (errors.length > 0) {
      throw new Error(`Secret validation failed:\n${errors.join('\n')}`);
    }

    console.log(`✓ All ${requiredSecrets.length} required secrets validated`);
  }
}

// Singleton instance
let secretsManagerInstance = null;

function getSecretsManager() {
  if (!secretsManagerInstance) {
    secretsManagerInstance = new SecretsManager();
  }
  return secretsManagerInstance;
}

module.exports = { SecretsManager, getSecretsManager };

// config.js - Centralized configuration with secrets management

const { getSecretsManager } = require('./secrets-manager');

class Config {
  constructor() {
    this.loaded = false;
    this.config = {};
    this.secretsManager = getSecretsManager();
  }

  /**
   * Load all configuration and secrets
   */
  async load() {
    if (this.loaded) return this.config;

    console.log('Loading application configuration...');

    // 1. Load non-sensitive config from environment
    this.config = {
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT || '3000'),
      logLevel: process.env.LOG_LEVEL || 'info',

      // Rate limiting
      rateLimit: {
        windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // 15 min
        maxRequests: parseInt(process.env.RATE_LIMIT_MAX || '100')
      },

      // CORS
      cors: {
        origins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000']
      },

      // Security
      security: {
        jwtExpiresIn: process.env.JWT_EXPIRES_IN || '1h',
        bcryptRounds: parseInt(process.env.BCRYPT_ROUNDS || '12'),
        sessionTimeout: parseInt(process.env.SESSION_TIMEOUT || '3600000') // 1 hour
      }
    };

    // 2. Load sensitive secrets from secrets manager
    try {
      await this.secretsManager.initialize();

      // Define which secrets to load based on environment
      const requiredSecrets = this.getRequiredSecrets();

      // Validate all required secrets exist
      await this.secretsManager.validateSecrets(requiredSecrets);

      // Load secrets
      this.config.secrets = {};

      // Database credentials
      if (requiredSecrets.includes('DATABASE_URL')) {
        this.config.secrets.databaseUrl = await this.secretsManager.getSecret('DATABASE_URL');
      }

      // AWS credentials
      if (requiredSecrets.includes('AWS_ACCESS_KEY_ID')) {
        this.config.secrets.awsAccessKeyId = await this.secretsManager.getSecret('AWS_ACCESS_KEY_ID');
        this.config.secrets.awsSecretAccessKey = await this.secretsManager.getSecret('AWS_SECRET_ACCESS_KEY');
      }

      // JWT Secret
      if (requiredSecrets.includes('JWT_SECRET')) {
        this.config.secrets.jwtSecret = await this.secretsManager.getSecret('JWT_SECRET');
      }

      // API Keys
      if (requiredSecrets.includes('ANTHROPIC_API_KEY')) {
        this.config.secrets.anthropicApiKey = await this.secretsManager.getSecret('ANTHROPIC_API_KEY');
      }

      if (requiredSecrets.includes('STRIPE_SECRET_KEY')) {
        this.config.secrets.stripeSecretKey = await this.secretsManager.getSecret('STRIPE_SECRET_KEY');
      }

      if (requiredSecrets.includes('LOGFIRE_TOKEN')) {
        this.config.secrets.logfireToken = await this.secretsManager.getSecret('LOGFIRE_TOKEN');
      }

      this.loaded = true;
      console.log('✓ Configuration loaded successfully');

      return this.config;
    } catch (error) {
      console.error('Failed to load configuration:', error.message);
      throw new Error('Configuration initialization failed');
    }
  }

  /**
   * Get required secrets based on environment
   */
  getRequiredSecrets() {
    const secrets = ['JWT_SECRET'];

    // Add environment-specific secrets
    if (this.config.env === 'production') {
      secrets.push(
        'DATABASE_URL',
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY',
        'STRIPE_SECRET_KEY',
        'LOGFIRE_TOKEN'
      );
    } else if (this.config.env === 'development') {
      // Fewer requirements for development
      secrets.push('DATABASE_URL');
    }

    // Add feature-specific secrets
    if (process.env.ENABLE_AI_FEATURES === 'true') {
      secrets.push('ANTHROPIC_API_KEY');
    }

    return secrets;
  }

  /**
   * Get configuration value
   */
  get(path) {
    if (!this.loaded) {
      throw new Error('Configuration not loaded. Call load() first.');
    }

    const keys = path.split('.');
    let value = this.config;

    for (const key of keys) {
      if (value === undefined || value === null) {
        return undefined;
      }
      value = value[key];
    }

    return value;
  }

  /**
   * Get secret value (with masking in logs)
   */
  getSecret(secretName) {
    if (!this.loaded) {
      throw new Error('Configuration not loaded. Call load() first.');
    }

    const secret = this.config.secrets?.[secretName];
    if (!secret) {
      throw new Error(`Secret ${secretName} not found`);
    }

    return secret;
  }

  /**
   * Check if running in production
   */
  isProduction() {
    return this.config.env === 'production';
  }

  /**
   * Check if running in development
   */
  isDevelopment() {
    return this.config.env === 'development';
  }

  /**
   * Reload configuration (useful for secret rotation)
   */
  async reload() {
    this.loaded = false;
    this.secretsManager.clearCache();
    return await this.load();
  }
}

// Singleton instance
let configInstance = null;

async function getConfig() {
  if (!configInstance) {
    configInstance = new Config();
    await configInstance.load();
  }
  return configInstance;
}

module.exports = { Config, getConfig };

// app.js - Secure version with proper secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const { getConfig } = require('./config');

// ============================================
// INITIALIZE APP WITH SECRETS
// ============================================
async function createApp() {
  const app = express();

  // Load configuration (including secrets from secrets manager)
  let config;
  try {
    config = await getConfig();
    console.log('✓ Application configuration loaded');
  } catch (error) {
    console.error('❌ Failed to load configuration:', error.message);
    process.exit(1);
  }

  // ============================================
  // SECURITY MIDDLEWARE
  // ============================================

  // Helmet for security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    },
    frameguard: { action: 'deny' },
    noSniff: true,
  }));

  // Disable powered-by header
  app.disable('x-powered-by');

  // CORS configuration from config
  const corsOptions = {
    origin: config.get('cors.origins'),
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400
  };
  app.use(cors(corsOptions));

  // Body parser with size limits
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ extended: true, limit: '10kb' }));

  // Request logging (mask sensitive data)
  morgan.token('sanitized-url', (req) => {
    // Remove sensitive query parameters from logs
    const url = new URL(req.url, `http://${req.headers.host}`);
    ['token', 'api_key', 'password', 'secret'].forEach(param => {
      if (url.searchParams.has(param)) {
        url.searchParams.set(param, '[REDACTED]');
      }
    });
    return url.pathname + url.search;
  });

  app.use(morgan(':method :sanitized-url :status :response-time ms'));

  // Rate limiting from config
  const limiter = rateLimit({
    windowMs: config.get('rateLimit.windowMs'),
    max: config.get('rateLimit.maxRequests'),
    standardHeaders: true,
    legacyHeaders: false,
    message: 'Too many requests from this IP, please try again later.'
  });
  app.use(limiter);

  // HTTPS enforcement in production
  if (config.isProduction()) {
    app.use((req, res, next) => {
      if (req.header('x-forwarded-proto') !== 'https') {
        return res.redirect(`https://${req.header('host')}${req.url}`);
      }
      next();
    });
  }

  // ============================================
  // AUTHENTICATION MIDDLEWARE
  // ============================================
  const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({ 
        error: 'Authentication required',
        message: 'Access token is missing'
      });
    }

    // Use JWT secret from secrets manager
    const jwtSecret = config.getSecret('jwtSecret');

    jwt.verify(token, jwtSecret, (err, user) => {
      if (err) {
        // Log failed authentication attempt
        console.warn('Failed authentication attempt:', {
          ip: req.ip,
          timestamp: new Date().toISOString(),
          error: err.message
        });

        return res.status(403).json({ 
          error: 'Forbidden',
          message: 'Invalid or expired token'
        });
      }
      req.user = user;
      next();
    });
  };

  // ============================================
  // ROUTES
  // ============================================

  // Health check - public endpoint (no secrets exposed)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: config.get('env'),
      // Never expose secrets in health check
      version: process.env.APP_VERSION || '1.0.0'
    });
  });

  // Secrets health check - for monitoring (protected)
  app.get('/health/secrets', authenticateToken, async (req, res) => {
    // Only allow system administrators
    if (!req.user.roles?.includes('system-admin')) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    try {
      // Check if we can access secrets (don't expose values)
      const secretChecks = {
        jwtSecret: !!config.getSecret('jwtSecret'),
        database: !!config.getSecret('databaseUrl')
      };

      res.json({
        status: 'ok',
        secretsAccessible: Object.values(secretChecks).every(Boolean),
        checks: Object.keys(secretChecks).reduce((acc, key) => {
          acc[key] = secretChecks[key] ? 'accessible' : 'missing';
          return acc;
        }, {})
      });
    } catch (error) {
      res.status(500).json({
        status: 'error',
        message: 'Unable to verify secrets access'
      });
    }
  });

  // Users endpoint - protected with authentication
  app.get('/users', 
    authenticateToken,
    [
      query('page').optional().isInt({ min: 1 }).toInt(),
      query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    ],
    async (req, res, next) => {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array()
        });
      }

      // Check permissions
      if (!req.user.permissions?.includes('read:users')) {
        return res.status(403).json({ 
          error: 'Forbidden',
          message: 'Insufficient permissions'
        });
      }

      try {
        // In production, use database connection with secrets from secrets manager
        // const dbUrl = config.getSecret('databaseUrl');
        // const db = await connectToDatabase(dbUrl);
        // const users = await db.query('SELECT id, name, email FROM users LIMIT $1', [limit]);

        const users = [
          { id: 1, name: 'Alice', email: 'alice@example.com' },
          { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        res.json({
          data: users,
          meta: {
            page: parseInt(req.query.page) || 1,
            limit: parseInt(req.query.limit) || 10
          }
        });
      } catch (error) {
        next(error);
      }
    }
  );

  // Endpoint to trigger secret rotation (admin only)
  app.post('/admin/rotate-secrets', authenticateToken, async (req, res) => {
    if (!req.user.roles?.includes('system-admin')) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    try {
      await config.reload();

      // Log security event
      console.info('Secret rotation completed:', {
        triggeredBy: req.user.id,
        timestamp: new Date().toISOString(),
        ip: req.ip
      });

      res.json({
        success: true,
        message: 'Secrets rotated successfully'
      });
    } catch (error) {
      console.error('Secret rotation failed:', error.message);
      res.status(500).json({
        error: 'Secret rotation failed'
      });
    }
  });

  // ============================================
  // ERROR HANDLING
  // ============================================

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({ 
      error: 'Not Found',
      message: 'The requested resource does not exist'
    });
  });

  // Global error handler
  app.use((err, req, res, next) => {
    // Never log secrets
    const sanitizedError = {
      timestamp: new Date().toISOString(),
      message: err.message,
      path: req.path,
      method: req.method,
      ip: req.ip
    };

    // Only include stack trace in development
    if (config.isDevelopment()) {
      sanitizedError.stack = err.stack;
    }

    console.error('Application error:', sanitizedError);

    const statusCode = err.statusCode || 500;
    const message = config.isProduction() 
      ? 'Internal server error' 
      : err.message;

    res.status(statusCode).json({
      error: message,
      ...(config.isDevelopment() && { stack: err.stack })
    });
  });

  return app;
}

// ============================================
// SERVER STARTUP
// ============================================
async function startServer() {
  try {
    const app = await createApp();
    const config = await getConfig();
    const PORT = config.get('port');

    const server = app.listen(PORT, () => {
      console.log(`✓ Server running on port ${PORT}`);
      console.log(`✓ Environment: ${config.get('env')}`);
      console.log(`✓ Secrets provider: ${process.env.SECRETS_PROVIDER || 'env'}`);
    });

    // Graceful shutdown
    const shutdown = async (signal) => {
      console.log(`\n${signal} received: closing HTTP server`);
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force close after 10 seconds
      setTimeout(() => {
        console.error('Forced shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

    return server;
  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start server if run directly
if (require.main === module) {
  startServer();
}

module.exports = { createApp, startServer };

