      if (Date.now() - cached.timestamp < 300000) { // 5 min TTL
        return cached.value;
      }
    }

    try {
      const secret = await this.client.getSecret(secretName);

      // Cache the secret
      this.cache.set(secretName, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getAllSecrets() {
