  async getSecret(secretName, version = 'latest') {
    const name = `projects/${this.projectId}/secrets/${secretName}/versions/${version}`;

    try {
      const [response] = await this.client.accessSecretVersion({ name });
      const payload = response.payload.data.toString('utf8');

      // Try to parse as JSON, otherwise return as string
      try {
        return JSON.parse(payload);
      } catch {
        return payload;
      }
    } catch (error) {
      console.error(`Failed to access secret ${secretName}:`, error);
      throw error;
    }
  }

  async createSecret(secretName, secretValue) {
    const parent = `projects/${this.projectId}`;

    try {
      // Create the secret
      await this.client.createSecret({
        parent: parent,
        secretId: secretName,
        secret: {
          replication: {
            automatic: {},
          },
        },
      });

      // Add secret version with data
      await this.client.addSecretVersion({
        parent: `${parent}/secrets/${secretName}`,
        payload: {
          data: Buffer.from(secretValue, 'utf8'),
        },
      });

      console.log(`Secret ${secretName} created successfully`);
    } catch (error) {
      console.error(`Failed to create secret ${secretName}:`, error);
      throw error;
    }
  }
}

