# SECURITY ADDENDUM: Secrets Management

## 🚨 Critical Finding: Insecure Secrets Management

### Issue Identified
The current implementation uses .env files for secrets management, which has several security risks:

1. **Secrets in version control risk** - .env files may be accidentally committed
2. **No access control** - Anyone with filesystem access can read secrets
3. **No audit trail** - No logging of secret access
4. **No rotation mechanism** - Difficult to rotate secrets regularly
5. **No encryption at rest** - Secrets stored in plaintext on disk

---

## ⚠️ DO NOT:
- ❌ Read or display actual secret values
- ❌ Log secret values anywhere
- ❌ Copy secrets to spreadsheets or documents
- ❌ Send secrets via email or chat
- ❌ Commit .env files to version control

---

## ✅ RECOMMENDED: Use a Secrets Manager

### Option 1: AWS Secrets Manager (Recommended for Production)

```javascript
// secrets.js - Secrets Manager Integration
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }

  // Clear cache on demand (useful for rotation)
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new SecretsManager();
```

### Usage in Application:

```javascript
// app.js
const express = require('express');
const secretsManager = require('./secrets');

const app = express();

// Initialize secrets on startup
let appSecrets;

async function initializeApp() {
  try {
    // Retrieve secrets from AWS Secrets Manager
    appSecrets = await secretsManager.getSecret('myapp/production/secrets');

    // Now use secrets
    const JWT_SECRET = appSecrets.JWT_SECRET;
    const DB_PASSWORD = appSecrets.DB_PASSWORD;

    // NEVER log actual secret values
    console.log('Secrets loaded successfully');

    // Continue app initialization...
    app.listen(3000);
  } catch (error) {
    console.error('Failed to initialize app:', error.message);
    process.exit(1);
  }
}

initializeApp();
```

---

### Option 2: HashiCorp Vault

```javascript
// vault-secrets.js
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN // This should come from k8s service account
    });
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(path);
      return result.data;
    } catch (error) {
      console.error(`Error reading secret from ${path}:`, error.message);
      throw new Error('Failed to retrieve secret from Vault');
    }
  }

  async rotateSecret(path, newValue) {
    try {
      await this.client.write(path, { data: newValue });
      console.log(`Secret at ${path} rotated successfully`);
    } catch (error) {
      console.error(`Error rotating secret at ${path}:`, error.message);
      throw error;
    }
  }
}

module.exports = new VaultSecretsManager();
```

---

### Option 3: Azure Key Vault

```javascript
// azure-secrets.js
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureSecretsManager {
  constructor() {
    const vaultName = process.env.KEY_VAULT_NAME;
    const vaultUrl = `https://${vaultName}.vault.azure.net`;

    this.client = new SecretClient(
      vaultUrl, 
      new DefaultAzureCredential()
    );
  }

  async getSecret(secretName) {
    try {
      const secret = await this.client.getSecret(secretName);
      return secret.value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }
}

module.exports = new AzureSecretsManager();
```

---

### Option 4: Google Cloud Secret Manager

```javascript
// gcp-secrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
  }

  async getSecret(secretName) {
    try {
      const name = `projects/${this.projectId}/secrets/${secretName}/versions/latest`;
      const [version] = await this.client.accessSecretVersion({ name });

      const payload = version.payload.data.toString('utf8');
      return payload;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }
}

module.exports = new GCPSecretsManager();
```

---

## 🔄 Secrets Rotation Strategy

### Automated Rotation Process:

```javascript
// rotation-handler.js
const secretsManager = require('./secrets');

class SecretRotationHandler {
  async rotateSecret(secretName) {
    try {
      // 1. Generate new secret
      const newSecret = this.generateSecureSecret();

      // 2. Update in secrets manager
      await secretsManager.updateSecret(secretName, newSecret);

      // 3. Clear local cache
      secretsManager.clearCache(secretName);

      // 4. Notify application to reload (graceful restart)
      this.notifyApplicationReload();

      // 5. Log rotation (without secret value)
      console.log({
        event: 'secret_rotated',
        secretName: secretName,
        timestamp: new Date().toISOString(),
        rotatedBy: 'automated'
      });

      return true;
    } catch (error) {
      console.error('Secret rotation failed:', error.message);
      throw error;
    }
  }

  generateSecureSecret(length = 32) {
    const crypto = require('crypto');
    return crypto.randomBytes(length).toString('base64');
  }

  notifyApplicationReload() {
    // Send signal to reload without downtime
    process.kill(process.pid, 'SIGUSR2');
  }
}

module.exports = new SecretRotationHandler();
```

