**Issue:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Problems:**
- No authentication required
- Anyone can access user data
- No authorization checks
- No rate limiting

**Fix:**
```javascript
// Add authentication middleware
const authenticateJWT = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users', authenticateJWT, (req, res) => {
  // ... implementation
});
```

---

### 2. Sensitive Data Exposure (HIGH)

**Issue:**
- Email addresses exposed in plain text
- No data masking
- No field-level security

**Fix:**
```javascript
// Mask sensitive data in responses
const maskEmail = (email) => {
  const [name, domain] = email.split('@');
  const maskedName = name.charAt(0) + '*'.repeat(name.length - 1);
  return `${maskedName}@${domain}`;
};

app.get('/users', authenticateJWT, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
    { id: 2, name: 'Bob', email: maskEmail('bob@example.com') },
  ];
  res.json(users);
});
```

---

### 3. Injection Attacks (HIGH)

**Issue:**
- No input validation
- Future endpoints vulnerable to SQL/NoSQL injection
- No sanitization of query parameters

**Fix:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticateJWT,
  [
    query('id').optional().isInt().toInt(),
    query('search').optional().trim().escape(),
    query('page').optional().isInt({ min: 1 }).toInt(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query.id, req.query.search, etc.
  }
);
```

**For database queries, always use parameterized statements:**
```javascript
// ❌ VULNERABLE to SQL Injection
const query = `SELECT * FROM users WHERE id = ${req.query.id}`;

// ✅ SAFE - Parameterized query
const query = 'SELECT * FROM users WHERE id = $1';
db.query(query, [req.query.id]);

// ✅ SAFE - ORM/ODM
User.findById(req.query.id);
```

---

### 4. Missing Security Headers (HIGH)

**Issue:**
- No protection against XSS
- No clickjacking protection
- No MIME sniffing prevention

**Fix:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));
```

---

### 5. No Rate Limiting (HIGH)

**Issue:**
- Vulnerable to DoS attacks
- Brute force attacks possible
- Resource exhaustion

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Stricter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});

app.use('/users', strictLimiter);
```

---

### 6. Missing CORS Configuration (MEDIUM)

**Issue:**
- Any origin can access the API
- No credentials control

**Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://yourdomain.com', 'https://app.yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));
```

---

### 7. No Error Handling (MEDIUM)

**Issue:**
- Unhandled errors may crash the application
- Stack traces could leak in production

**Fix:**
```javascript
// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: 'Error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});
```

---

### 8. No Logging/Monitoring (MEDIUM)

**Issue:**
- No audit trail
- Cannot detect security incidents
- No request logging

**Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Application logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  next();
});
```

