// Secure Secrets Manager Integration
// Supports multiple providers: AWS Secrets Manager, Azure Key Vault, HashiCorp Vault

const { 
  SecretsManagerClient, 
  GetSecretValueCommand 
} = require('@aws-sdk/client-secrets-manager');

const { 
  SecretClient 
} = require('@azure/keyvault-secrets');

const { DefaultAzureCredential } = require('@azure/identity');

/**
 * Unified Secrets Manager
 * Supports AWS, Azure, and HashiCorp Vault
 */
class SecretsManager {
  constructor(provider = 'aws') {
    this.provider = provider;
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
    this.initialized = false;
  }

  /**
   * Initialize the secrets manager
   */
  async initialize() {
    if (this.initialized) return;

    try {
      switch (this.provider) {
        case 'aws':
          this.client = new SecretsManagerClient({
            region: process.env.AWS_REGION || 'us-east-1',
          });
          break;

        case 'azure':
          const vaultUrl = process.env.AZURE_KEY_VAULT_URL;
          if (!vaultUrl) {
            throw new Error('AZURE_KEY_VAULT_URL is required');
          }
          const credential = new DefaultAzureCredential();
          this.client = new SecretClient(vaultUrl, credential);
          break;

        case 'vault':
          // HashiCorp Vault implementation
          const vault = require('node-vault');
          this.client = vault({
            endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
            token: process.env.VAULT_TOKEN,
          });
          break;

        default:
          throw new Error(`Unsupported provider: ${this.provider}`);
      }

      this.initialized = true;
      console.info(`[SECRETS] Initialized ${this.provider} secrets manager`);
    } catch (error) {
      console.error(`[SECRETS] Failed to initialize: ${error.message}`);
      throw error;
    }
  }

  /**
   * Get a secret from the secrets manager with caching
   */
  async getSecret(secretName, options = {}) {
    if (!this.initialized) {
      await this.initialize();
    }

    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      console.debug(`[SECRETS] Cache hit for: ${secretName}`);
      return cached.value;
    }

    try {
      let secretValue;

      switch (this.provider) {
        case 'aws':
          secretValue = await this.getAwsSecret(secretName);
          break;
        case 'azure':
          secretValue = await this.getAzureSecret(secretName);
          break;
        case 'vault':
          secretValue = await this.getVaultSecret(secretName);
          break;
        default:
          throw new Error(`Unknown provider: ${this.provider}`);
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      console.info(`[SECRETS] Retrieved secret: ${secretName}`);
      return secretValue;
    } catch (error) {
      console.error(`[SECRETS] Failed to get secret ${secretName}: ${error.message}`);

      // If required, throw error; otherwise return fallback
      if (options.required) {
        throw new Error(`Required secret ${secretName} not found`);
      }

      return options.default || null;
    }
  }

  /**
   * AWS Secrets Manager implementation
   */
  async getAwsSecret(secretName) {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
    });

    const response = await this.client.send(command);

    // Handle both string and binary secrets
    if (response.SecretString) {
      try {
        // Try to parse as JSON
        return JSON.parse(response.SecretString);
      } catch {
        // Return as plain string
        return response.SecretString;
      }
    }

    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    throw new Error('Secret has no value');
  }

  /**
   * Azure Key Vault implementation
   */
  async getAzureSecret(secretName) {
    const secret = await this.client.getSecret(secretName);
    return secret.value;
  }

  /**
   * HashiCorp Vault implementation
   */
  async getVaultSecret(secretName) {
    const result = await this.client.read(`secret/data/${secretName}`);
    return result.data.data;
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => 
      this.getSecret(name).catch(err => {
        console.warn(`[SECRETS] Failed to get ${name}: ${err.message}`);
        return null;
      })
    );

    const results = await Promise.all(promises);

    return secretNames.reduce((acc, name, index) => {
      acc[name] = results[index];
      return acc;
    }, {});
  }

  /**
   * Clear the cache
   */
  clearCache() {
    this.cache.clear();
    console.info('[SECRETS] Cache cleared');
  }

  /**
   * Validate required secrets are present
   */
  async validateSecrets(requiredSecrets) {
    const missing = [];

    for (const secretName of requiredSecrets) {
      try {
        const value = await this.getSecret(secretName, { required: true });
        if (!value) {
          missing.push(secretName);
        }
      } catch (error) {
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.info('[SECRETS] All required secrets validated');
    return true;
  }

  /**
   * Rotate secret (implementation depends on provider)
   */
  async rotateSecret(secretName) {
    console.info(`[SECRETS] Rotating secret: ${secretName}`);

    switch (this.provider) {
      case 'aws':
        const { RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');
        const command = new RotateSecretCommand({ SecretId: secretName });
        await this.client.send(command);
        break;

      case 'azure':
      case 'vault':
        // Implementation specific to provider
        throw new Error('Rotation not implemented for this provider');

      default:
        throw new Error('Unknown provider');
    }

    // Clear from cache
    this.cache.delete(secretName);
    console.info(`[SECRETS] Secret rotated: ${secretName}`);
  }
}

// Singleton instance
let secretsManagerInstance = null;

/**
 * Get or create the secrets manager instance
 */
function getSecretsManager(provider) {
  if (!secretsManagerInstance) {
    const secretProvider = provider || 
      process.env.SECRETS_PROVIDER || 
      'aws';

    secretsManagerInstance = new SecretsManager(secretProvider);
  }
  return secretsManagerInstance;
}

/**
 * Helper: Load all application secrets
 */
async function loadApplicationSecrets() {
  const manager = getSecretsManager();

  // Define your application's secrets
  const secretsConfig = {
    // AWS Secrets Manager / Azure Key Vault / Vault path
    jwtSecret: process.env.SECRET_NAME_JWT || 'app/jwt-secret',
    apiKeys: process.env.SECRET_NAME_API_KEYS || 'app/api-keys',
    databaseUrl: process.env.SECRET_NAME_DB || 'app/database-url',
    encryptionKey: process.env.SECRET_NAME_ENCRYPTION || 'app/encryption-key',
  };

  try {
    const secrets = {};

    for (const [key, secretName] of Object.entries(secretsConfig)) {
      secrets[key] = await manager.getSecret(secretName, {
        required: true,
      });
    }

    // Validate secret strength
    validateSecretStrength(secrets.jwtSecret, 'JWT_SECRET');

    return secrets;
  } catch (error) {
    console.error('[SECRETS] Failed to load application secrets:', error.message);
    throw error;
  }
}

/**
 * Validate secret strength
 */
function validateSecretStrength(secret, name) {
  if (!secret || typeof secret !== 'string') {
    throw new Error(`${name} must be a string`);
  }

  if (secret.length < 32) {
    throw new Error(`${name} must be at least 32 characters`);
  }

  // Check for common weak secrets
  const weakSecrets = ['secret', 'password', '12345', 'admin', 'test'];
  const lowerSecret = secret.toLowerCase();

  for (const weak of weakSecrets) {
    if (lowerSecret.includes(weak)) {
      throw new Error(`${name} contains weak pattern: ${weak}`);
    }
  }

  console.debug(`[SECRETS] ${name} validated successfully`);
}

/**
 * Development fallback (NOT FOR PRODUCTION)
 */
async function loadDevelopmentSecrets() {
  console.warn('⚠️  [SECRETS] Using development mode - NOT FOR PRODUCTION');

  // Load from .env only in development
  if (process.env.NODE_ENV === 'development') {
    require('dotenv').config();
  } else {
    throw new Error('Cannot use development secrets in production');
  }

  return {
    jwtSecret: process.env.JWT_SECRET,
    apiKeys: process.env.VALID_API_KEYS?.split(',') || [],
    databaseUrl: process.env.DATABASE_URL,
    encryptionKey: process.env.ENCRYPTION_KEY,
  };
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  loadApplicationSecrets,
  loadDevelopmentSecrets,
};

