module.exports = {
  SecretsManager,
  getSecretsManager,
  loadApplicationSecrets,
  loadDevelopmentSecrets,
};

// Production-Ready Secure Express.js Application
// WITH PROPER SECRETS MANAGEMENT
// Addresses OWASP Top 10 vulnerabilities + Secrets Management

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
const { loadApplicationSecrets, loadDevelopmentSecrets } = require('./secrets-manager');

const app = express();

// ===========================
// 0. SECRETS LOADING
// ===========================

let appSecrets = null;

/**
 * Initialize secrets from Secrets Manager
 * This runs BEFORE the server starts
 */
async function initializeSecrets() {
  try {
    console.info('[INIT] Loading application secrets...');

    if (process.env.NODE_ENV === 'production') {
      // ✅ SECURE: Load from AWS Secrets Manager / Azure Key Vault / Vault
      appSecrets = await loadApplicationSecrets();
      console.info('[INIT] ✅ Secrets loaded from Secrets Manager');
    } else {
      // Development mode - load from .env (with warning)
      console.warn('[INIT] ⚠️  Development mode - using .env (NOT FOR PRODUCTION)');
      appSecrets = await loadDevelopmentSecrets();
    }

    // Validate required secrets are present
    const requiredSecrets = ['jwtSecret', 'apiKeys'];
    for (const key of requiredSecrets) {
      if (!appSecrets[key]) {
        throw new Error(`Required secret missing: ${key}`);
      }
    }

    console.info('[INIT] ✅ All required secrets validated');

  } catch (error) {
    console.error('[INIT] ❌ Failed to load secrets:', error.message);
    console.error('[INIT] Application cannot start without secrets');
    process.exit(1);
  }
}

// ===========================
// 1. SECURITY MIDDLEWARE
// ===========================

// Set security HTTP headers (prevents XSS, clickjacking, etc.)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// CORS configuration - restrict to specific origins in production
const getCorsOptions = () => {
  // ✅ SECURE: CORS origins could also come from Secrets Manager
  const allowedOrigins = process.env.NODE_ENV === 'production'
    ? (appSecrets?.allowedOrigins || ['https://yourdomain.com'])
    : ['http://localhost:3000', 'http://localhost:3001'];

  return {
    origin: allowedOrigins,
    optionsSuccessStatus: 200,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key']
  };
};

// Delay CORS setup until secrets are loaded
let corsMiddleware;

// Body parser with size limits (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// Logging (use appropriate level for production)
if (process.env.NODE_ENV === 'development') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// ===========================
// 2. RATE LIMITING
// ===========================

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false,
});

app.use('/api/', generalLimiter);

// ===========================
// 3. AUTHENTICATION MIDDLEWARE
// ===========================

/**
 * API Key Authentication
 * ✅ SECURE: API keys loaded from Secrets Manager
 */
const authenticateApiKey = (req, res, next) => {
  // Check if secrets are loaded
  if (!appSecrets) {
    console.error('[AUTH] Secrets not loaded');
    return res.status(503).json({ 
      error: 'Service Unavailable',
      message: 'System is initializing' 
    });
  }

  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ 
      error: 'Unauthorized', 
      message: 'API key is required' 
    });
  }

  // ✅ SECURE: Validate against keys from Secrets Manager
  const validApiKeys = Array.isArray(appSecrets.apiKeys) 
    ? appSecrets.apiKeys 
    : appSecrets.apiKeys.split(',');

  if (!validApiKeys.includes(apiKey)) {
    // Log suspicious activity
    console.warn(`[SECURITY] Invalid API key attempt from IP: ${req.ip}`);
    return res.status(403).json({ 
      error: 'Forbidden', 
      message: 'Invalid API key' 
    });
  }

  next();
};

/**
 * JWT Authentication
 * ✅ SECURE: JWT secret loaded from Secrets Manager
 */
const jwt = require('jsonwebtoken');

const authenticateJWT = (req, res, next) => {
  // Check if secrets are loaded
  if (!appSecrets || !appSecrets.jwtSecret) {
    console.error('[AUTH] JWT secret not loaded');
    return res.status(503).json({ 
      error: 'Service Unavailable',
      message: 'System is initializing' 
    });
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      error: 'Unauthorized', 
      message: 'Access token is required' 
    });
  }

  const token = authHeader.split(' ')[1];

  try {
    // ✅ SECURE: Use JWT secret from Secrets Manager
    const decoded = jwt.verify(token, appSecrets.jwtSecret);
    req.user = decoded;
    next();
  } catch (err) {
    console.warn(`[SECURITY] Invalid token attempt from IP: ${req.ip}`, err.message);
    return res.status(403).json({ 
      error: 'Forbidden', 
      message: 'Invalid or expired token' 
    });
  }
};

// ===========================
// 4. INPUT VALIDATION HELPERS
// ===========================

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation Error',
      details: errors.array() 
    });
  }
  next();
};

// ===========================
// 5. ROUTES (SECURED)
// ===========================

// Health check endpoint (public)
app.get('/health', (req, res) => {
  const secretsStatus = appSecrets ? 'loaded' : 'not_loaded';

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    secrets: secretsStatus  // Don't expose actual secrets!
  });
});

// Users endpoint (secured with authentication and validation)
app.get('/users', 
  authenticateApiKey,
  strictLimiter,
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('search').optional().trim().escape(),
  ],
  validateRequest,
  (req, res) => {
    // In production, fetch from database with proper parameterized queries
    // This prevents SQL/NoSQL injection

    // Sanitized user data - emails partially masked for privacy
    const users = [
      { id: 1, name: 'Alice', email: 'a****@example.com' },
      { id: 2, name: 'Bob', email: 'b****@example.com' },
    ];

    // Apply pagination
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    // Log access for audit trail
    console.info(`[AUDIT] Users accessed by API key from IP: ${req.ip}`);

    res.json({
      success: true,
      data: users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  }
);

// Login endpoint - generates JWT
app.post('/login',
  strictLimiter,
  [
    body('username').trim().notEmpty().isLength({ min: 3, max: 50 }),
    body('password').notEmpty().isLength({ min: 8 }),
  ],
  validateRequest,
  async (req, res) => {
    const { username, password } = req.body;

    // In production: Verify against database with bcrypt
    // This is just an example
    if (username === 'demo' && password === 'password123') {

      // ✅ SECURE: Sign JWT with secret from Secrets Manager
      const token = jwt.sign(
        { 
          userId: 1, 
          username: username,
          role: 'user'
        },
        appSecrets.jwtSecret,
        { 
          expiresIn: '7d',
          issuer: 'your-app-name',
          audience: 'your-app-users'
        }
      );

      console.info(`[AUDIT] User logged in: ${username} from IP: ${req.ip}`);

      return res.json({
        success: true,
        token,
        expiresIn: '7d'
      });
    }

    console.warn(`[SECURITY] Failed login attempt: ${username} from IP: ${req.ip}`);

    res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid credentials'
    });
  }
);

// Protected endpoint using JWT
app.get('/profile',
  authenticateJWT,
  (req, res) => {
    console.info(`[AUDIT] Profile accessed by user: ${req.user.userId} from IP: ${req.ip}`);

    res.json({
      success: true,
      user: {
        id: req.user.userId,
        username: req.user.username,
        role: req.user.role
      }
    });
  }
);

// Example: Secure POST endpoint with full validation
app.post('/users',
  authenticateApiKey,
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters')
      .escape()
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Must be a valid email')
      .normalizeEmail()
      .isLength({ max: 100 }),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 }).withMessage('Age must be between 0 and 150')
      .toInt(),
  ],
  validateRequest,
  (req, res) => {
    const { name, email, age } = req.body;

    // In production: Use parameterized queries or ORM
    // Example with prepared statements:
    // const result = await db.query(
    //   'INSERT INTO users (name, email, age) VALUES ($1, $2, $3)',
    //   [name, email, age]
    // );

    console.info(`[AUDIT] User created: ${email} from IP: ${req.ip}`);

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        id: 3, // In production, return actual DB-generated ID
        name,
        email: email.replace(/(?<=.{1}).(?=.*@)/g, '*'), // Mask email in response
        age
      }
    });
  }
);

// ===========================
// 6. ERROR HANDLING
// ===========================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    path: req.originalUrl
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // ⚠️ IMPORTANT: Don't log secrets in errors
  const safeError = {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    url: req.originalUrl,
    method: req.method
  };

  console.error('[ERROR]', safeError);

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: 'Error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===========================
// 7. GRACEFUL SHUTDOWN
// ===========================

let server;

const shutdown = async (signal) => {
  console.info(`[SHUTDOWN] ${signal} received: closing HTTP server`);

  if (server) {
    server.close(() => {
      console.info('[SHUTDOWN] HTTP server closed');
      // Clear secrets from memory
      if (appSecrets) {
        Object.keys(appSecrets).forEach(key => {
          appSecrets[key] = null;
        });
        appSecrets = null;
      }
      process.exit(0);
    });

    // Force close after 30 seconds
    setTimeout(() => {
      console.error('[SHUTDOWN] Forcing shutdown after timeout');
      process.exit(1);
    }, 30000);
  } else {
    process.exit(0);
  }
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// ===========================
// 8. SERVER INITIALIZATION
// ===========================

async function startServer() {
  try {
    // STEP 1: Load secrets FIRST
    await initializeSecrets();

    // STEP 2: Set up CORS with loaded secrets
    corsMiddleware = cors(getCorsOptions());
    app.use(corsMiddleware);

    // STEP 3: Start server
    const PORT = process.env.PORT || 3000;
    server = app.listen(PORT, () => {
      console.log(`[SERVER] ✅ Secure server running on port ${PORT}`);
      console.log(`[SERVER] Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`[SERVER] Secrets Provider: ${process.env.SECRETS_PROVIDER || 'aws'}`);
      console.log(`[SERVER] Ready to accept connections`);
    });

  } catch (error) {
    console.error('[SERVER] ❌ Failed to start:', error.message);
    process.exit(1);
  }
}

// Start the application
if (require.main === module) {
  startServer();
}

module.exports = { app, startServer };
